import { useCallback, useEffect, useRef, useState } from 'react'
import { FONT_FAMILY } from './constants'
import type { MarkerAlign } from './types'

// SDK 오버레이 요소 ID — 픽커 대상에서 제외
// ※ specbridge-annot-container 는 제외하지 않음 (페이지 콘텐츠가 그 안에 있음)
const EXCLUDED_IDS = [
  'specbridge-annot-layer',
  'specbridge-pin-layer',
  'sb-element-picker-highlight',
  'sb-element-picker-popup',
  'sb-spec-drawer',            // SpecDrawer
]
// SDK UI 컴포넌트는 data-sb-ui="true" 속성으로도 마킹 (이중 제외)

interface HoveredEl {
  el: HTMLElement
  rect: DOMRect
}

interface NamingState {
  rect: DOMRect
  initialName: string
  pinX: number   // 핀 좌표 (0~1, 뷰포트 비율)
  pinY: number
}

interface Props {
  active: boolean
  align: MarkerAlign
  /** 이름까지 확정된 후 호출 */
  /** elementId, elementLabel, 핀 좌표(px) */
  onSelectElement: (elementId: string, elementLabel: string, pinX: number, pinY: number) => void
}

function isExcluded(el: HTMLElement): boolean {
  let cur: HTMLElement | null = el
  while (cur && cur !== document.body) {
    if (EXCLUDED_IDS.includes(cur.id)) return true
    // data-sb-ui 속성이 있으면 SDK UI → 제외
    if ((cur as HTMLElement & { dataset: DOMStringMap }).dataset?.sbUi) return true
    cur = cur.parentElement
  }
  return false
}

// ── 이름 지정 팝업 ─────────────────────────────────────────────────────────────

function NamingPopup({
  rect,
  initialName,
  onConfirm,
  onCancel,
}: {
  rect: DOMRect
  initialName: string
  onConfirm: (name: string) => void
  onCancel: () => void
}) {
  const [name, setName] = useState(initialName)
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    inputRef.current?.focus()
    inputRef.current?.select()
  }, [])

  // 팝업 위치: 요소 아래, 뷰포트 안에서 클램핑
  const popW = 240
  const popH = 96
  const margin = 8
  let left = rect.left
  let top  = rect.bottom + margin

  if (left + popW > window.innerWidth - margin)  left = window.innerWidth - popW - margin
  if (left < margin) left = margin
  if (top + popH > window.innerHeight - 50) top = rect.top - popH - margin

  const handleConfirm = () => {
    const trimmed = name.trim()
    if (!trimmed) return
    onConfirm(trimmed)
  }

  return (
    <div
      id="sb-element-picker-popup"
      style={{
        position: 'fixed',
        top, left,
        width: popW,
        background: 'rgba(8,12,24,.97)',
        backdropFilter: 'blur(20px)',
        WebkitBackdropFilter: 'blur(20px)',
        border: '1px solid rgba(99,102,241,.4)',
        borderRadius: 6,
        boxShadow: '0 8px 32px rgba(0,0,0,.5)',
        padding: '10px 12px',
        zIndex: 19999,
        fontFamily: FONT_FAMILY,
      }}
      onClick={(e) => e.stopPropagation()}
    >
      <div style={{ fontSize: 10, color: 'rgba(255,255,255,.4)', marginBottom: 6, letterSpacing: '.3px', fontWeight: 600 }}>
        요소 이름 지정
      </div>
      <input
        ref={inputRef}
        value={name}
        onChange={(e) => setName(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === 'Enter') { e.preventDefault(); handleConfirm() }
          if (e.key === 'Escape') onCancel()
        }}
        placeholder="예: 저장 버튼, 회원 테이블..."
        style={{
          width: '100%', boxSizing: 'border-box',
          background: 'rgba(255,255,255,.07)',
          border: '1px solid rgba(99,102,241,.4)',
          borderRadius: 4, padding: '6px 9px',
          color: '#fff', fontSize: 12,
          fontFamily: FONT_FAMILY, outline: 'none',
          marginBottom: 8,
        }}
      />
      <div style={{ display: 'flex', gap: 6 }}>
        <button
          onClick={onCancel}
          style={{
            flex: 1, padding: '5px 0', borderRadius: 3,
            background: 'transparent', border: '1px solid rgba(255,255,255,.12)',
            color: 'rgba(255,255,255,.45)', fontSize: 11,
            cursor: 'pointer', fontFamily: FONT_FAMILY,
          }}
        >취소</button>
        <button
          onClick={handleConfirm}
          disabled={!name.trim()}
          style={{
            flex: 2, padding: '5px 0', borderRadius: 3,
            background: name.trim() ? 'rgba(99,102,241,.7)' : 'rgba(255,255,255,.07)',
            border: 'none',
            color: name.trim() ? '#fff' : 'rgba(255,255,255,.25)',
            fontSize: 11, fontWeight: 600,
            cursor: name.trim() ? 'pointer' : 'not-allowed',
            fontFamily: FONT_FAMILY,
          }}
        >확인 →</button>
      </div>
    </div>
  )
}

// ── ElementPicker ─────────────────────────────────────────────────────────────

export function ElementPicker({ active, align, onSelectElement }: Props) {
  const [hovered, setHovered] = useState<HoveredEl | null>(null)
  const [naming, setNaming] = useState<NamingState | null>(null)
  const frameRef = useRef<number | null>(null)
  const hoveredRef = useRef<HoveredEl | null>(null)

  // hover 업데이트 (rAF throttle)
  const onMove = useCallback((e: MouseEvent) => {
    if (naming) return   // 팝업 열린 중엔 hover 갱신 안 함
    if (frameRef.current) cancelAnimationFrame(frameRef.current)
    frameRef.current = requestAnimationFrame(() => {
      const target = e.target as HTMLElement | null
      if (!target || isExcluded(target)) {
        setHovered(null)
        hoveredRef.current = null
        return
      }
      const el = target.closest<HTMLElement>('[id], button, a, input, select, textarea, [role], h1, h2, h3, h4, li, td, th, label, img, form, section, article, nav, header, footer, main, aside') ?? target
      if (isExcluded(el)) { setHovered(null); hoveredRef.current = null; return }
      const rect = el.getBoundingClientRect()
      const next = { el, rect }
      hoveredRef.current = next
      setHovered(next)
    })
  }, [naming])

  // 클릭 → 이름 팝업
  const onClick = useCallback((e: MouseEvent) => {
    // SDK UI(드로어, 툴바, 팝업 등) 내부 클릭은 무조건 패스
    const clickTarget = e.target as HTMLElement | null
    if (!clickTarget || isExcluded(clickTarget)) return

    const pinLayer = document.getElementById('specbridge-pin-layer')
    const layerRect = pinLayer?.getBoundingClientRect()
    if (!layerRect || layerRect.width === 0 || layerRect.height === 0) return

    e.preventDefault()
    e.stopPropagation()

    if (hoveredRef.current && !isExcluded(hoveredRef.current.el)) {
      // 요소가 hover된 경우: 요소 기준 좌표
      const { el, rect } = hoveredRef.current
      hoveredRef.current = null
      const rawX = rect.left - layerRect.left
      const pinX = align === 'center' ? rawX - layerRect.width / 2
                 : align === 'right'  ? layerRect.width - rawX
                 : rawX
      const pinY = rect.top - layerRect.top
      setNaming({ rect, initialName: el.dataset?.specLabel ?? '', pinX, pinY })
    } else {
      // 자유 위치: 클릭 지점 그대로 사용
      hoveredRef.current = null
      const rawX = e.clientX - layerRect.left
      const rawY = e.clientY - layerRect.top
      const pinX = align === 'center' ? rawX - layerRect.width / 2
                 : align === 'right'  ? layerRect.width - rawX
                 : rawX
      const fakeRect = new DOMRect(e.clientX, e.clientY, 0, 0)
      setNaming({ rect: fakeRect, initialName: '', pinX, pinY: rawY })
    }
    setHovered(null)
  }, [align])

  useEffect(() => {
    if (!active) {
      setHovered(null)
      setNaming(null)
      return
    }
    document.addEventListener('mousemove', onMove)
    document.addEventListener('click', onClick, true)
    return () => {
      document.removeEventListener('mousemove', onMove)
      document.removeEventListener('click', onClick, true)
      if (frameRef.current) cancelAnimationFrame(frameRef.current)
    }
  }, [active, onMove, onClick])

  useEffect(() => {
    if (!active) return
    document.body.style.cursor = 'crosshair'
    return () => { document.body.style.cursor = '' }
  }, [active])

  // ESC로 닫기
  useEffect(() => {
    if (!naming) return
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') setNaming(null) }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [naming])

  if (!active) return null

  return (
    <>
      {/* hover 하이라이트 */}
      {hovered && !naming && (() => {
        const { rect } = hovered
        const PAD = 2
        return (
          <div
            id="sb-element-picker-highlight"
            style={{
              position: 'fixed',
              top:    rect.top    - PAD,
              left:   rect.left   - PAD,
              width:  rect.width  + PAD * 2,
              height: rect.height + PAD * 2,
              border: '2px solid rgba(99,102,241,.75)',
              borderRadius: 3,
              background: 'rgba(99,102,241,.06)',
              pointerEvents: 'none',
              zIndex: 9800,
              boxShadow: '0 0 0 1px rgba(99,102,241,.15)',
            }}
          >
            <div style={{
              position: 'absolute', bottom: 'calc(100% + 4px)', left: 0,
              background: 'rgba(99,102,241,.9)', color: '#fff',
              fontSize: 10, fontWeight: 600, padding: '2px 8px',
              borderRadius: '3px 3px 3px 0', whiteSpace: 'nowrap',
              fontFamily: FONT_FAMILY, pointerEvents: 'none',
            }}>
              클릭하여 스펙 작성
            </div>
          </div>
        )
      })()}

      {/* 이름 지정 팝업 */}
      {naming && (
        <NamingPopup
          rect={naming.rect}
          initialName={naming.initialName}
          onConfirm={(name) => {
            const { pinX, pinY } = naming!
            setNaming(null)
            onSelectElement(name, name, pinX, pinY)
          }}
          onCancel={() => setNaming(null)}
        />
      )}
    </>
  )
}
