import { createPortal } from 'react-dom'
import { useEffect, useState } from 'react'
import { FONT_FAMILY } from './constants'
import type { MarkerAlign, PageSpec } from './types'

const PIN_LAYER_ID = 'specbridge-pin-layer'
const EXPAND_W = 220

function timeAgo(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime()
  if (diff < 60_000) return '방금'
  if (diff < 3_600_000) return `${Math.floor(diff / 60_000)}분 전`
  if (diff < 86_400_000) return `${Math.floor(diff / 3_600_000)}시간 전`
  return `${Math.floor(diff / 86_400_000)}일 전`
}

interface Props {
  spec: PageSpec
  align: MarkerAlign
  isExternalHovered?: boolean
  onClick: () => void
  onMove?: (pos: { pinX: number; pinY: number }) => void
  onMoveEnd?: (pos: { pinX: number; pinY: number }) => void
  softDeleted?: boolean
}

const SPEC_COLOR = '#ef4444'

export function SpecPin({ spec, align, isExternalHovered, onClick, onMove, onMoveEnd, softDeleted }: Props) {
  const [hovered, setHovered] = useState(false)
  const [dragging, setDragging] = useState(false)
  const [contentReady, setContentReady] = useState(false)

  const expanded = hovered || !!isExternalHovered

  useEffect(() => {
    if (!expanded) { setContentReady(false); return }
    const raf = requestAnimationFrame(() => setContentReady(true))
    return () => cancelAnimationFrame(raf)
  }, [expanded])

  if (spec.pinX == null || spec.pinY == null) return null

  const num = spec.num ?? '·'
  const label = spec.elementLabel ?? spec.elementId

  // 뷰포트 좌표 — 호버 버블 위치 계산용
  const { viewportX, viewportY, expandLeft } = (() => {
    const el = document.getElementById(PIN_LAYER_ID)
    const r = el?.getBoundingClientRect() ?? { left: 0, top: 0, width: window.innerWidth, height: window.innerHeight }
    const rawX = align === 'center' ? spec.pinX + r.width / 2
               : align === 'right'  ? r.width - spec.pinX
               : spec.pinX
    const vx = r.left + rawX
    const vy = r.top + spec.pinY
    return {
      viewportX: vx,
      viewportY: vy,
      expandLeft: vx + EXPAND_W > window.innerWidth - 8,
    }
  })()

  const EDGE = 8
  const MIN_UP = 120
  const expandDown = expanded && (viewportY + 28 - EDGE) < MIN_UP
  const maxExpandH = expanded
    ? expandDown
      ? Math.min(400, window.innerHeight - viewportY - EDGE)
      : Math.min(400, viewportY + 28 - EDGE)
    : 28

  const portalLeft = expandLeft ? viewportX + 28 - EXPAND_W : viewportX
  const portalVertical: React.CSSProperties = expandDown
    ? { top: viewportY }
    : { bottom: window.innerHeight - viewportY - 28 }

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button !== 0) return
    if (spec.pinX == null || spec.pinY == null) return
    e.stopPropagation()

    if (!onMove && !onMoveEnd) {
      onClick()
      return
    }

    const pinLayer = document.getElementById(PIN_LAYER_ID)
    if (!pinLayer) { onClick(); return }
    const base = pinLayer.getBoundingClientRect()

    const pinRawX = align === 'center' ? spec.pinX + base.width / 2
                  : align === 'right'  ? base.width - spec.pinX
                  : spec.pinX
    const startX = e.clientX - base.left - pinRawX
    const startY = e.clientY - base.top - spec.pinY

    let moved = false
    let lastPos = { pinX: spec.pinX, pinY: spec.pinY }

    const onMoveHandler = (ev: MouseEvent) => {
      if (!moved) { moved = true; setDragging(true) }
      const newRawX = ev.clientX - base.left - startX
      const newRawY = ev.clientY - base.top - startY
      const clampedRawX = Math.max(0, Math.min(base.width, newRawX))
      const clampedRawY = Math.max(0, Math.min(base.height, newRawY))
      const newPinX = align === 'center' ? clampedRawX - base.width / 2
                    : align === 'right'  ? base.width - clampedRawX
                    : clampedRawX
      lastPos = { pinX: newPinX, pinY: clampedRawY }
      onMove?.(lastPos)
    }

    const onUp = () => {
      document.removeEventListener('mousemove', onMoveHandler)
      document.removeEventListener('mouseup', onUp)
      setDragging(false)
      if (!moved) {
        onClick()
      } else {
        onMoveEnd?.(lastPos)
      }
    }

    document.addEventListener('mousemove', onMoveHandler)
    document.addEventListener('mouseup', onUp)
  }

  return (
    <>
      <div
        data-sb-ui="true"
        onMouseDown={handleMouseDown}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        title={label}
        style={{
          position: 'absolute',
          ...(align === 'center' ? { left: `calc(50% + ${spec.pinX}px)` }
            : align === 'right'  ? { right: `${spec.pinX}px` }
            : { left: `${spec.pinX}px` }),
          top: `${spec.pinY}px`,
          transform: 'translate(0, 0)',
          zIndex: 9850,
          cursor: dragging ? 'grabbing' : expanded ? 'grab' : 'pointer',
          pointerEvents: 'all',
          display: 'flex',
          alignItems: 'flex-start',
          transition: dragging ? 'none' : 'opacity .15s',
          opacity: softDeleted ? 0.4 : 1,
        }}
      >
        {/* 번호 배지 — AnnotPin 동일 구조 */}
        <div style={{
          width: 28,
          height: 28,
          borderRadius: '80px 80px 80px 12px',
          background: '#1A1A1A',
          boxShadow: '0 2px 8px rgba(0,0,0,.28)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          flexShrink: 0,
        }}>
          <div style={{
            width: 22,
            height: 22,
            borderRadius: '50%',
            background: SPEC_COLOR,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}>
            <span style={{
              fontSize: 10,
              fontWeight: 700,
              color: '#fff',
              fontFamily: FONT_FAMILY,
              lineHeight: 1,
              userSelect: 'none',
              textDecoration: softDeleted ? 'line-through' : 'none',
            }}>
              {num}
            </span>
          </div>
        </div>
      </div>

      {/* 호버 확장 버블 — createPortal → body */}
      {expanded && typeof document !== 'undefined' && createPortal(
        <div
          onMouseDown={handleMouseDown}
          onMouseEnter={() => setHovered(true)}
          onMouseLeave={() => setHovered(false)}
          style={{
            position: 'fixed',
            left: portalLeft,
            ...portalVertical,
            width: EXPAND_W,
            maxHeight: maxExpandH,
            minHeight: 28,
            borderRadius: expandDown ? '4px 16px 16px 16px' : '16px 16px 16px 4px',
            background: '#1A1A1A',
            boxShadow: '0 6px 18px rgba(0,0,0,.38)',
            overflow: 'hidden',
            zIndex: 9992,
            fontFamily: FONT_FAMILY,
            pointerEvents: 'all',
            display: 'flex',
            flexDirection: 'column',
            cursor: dragging ? 'grabbing' : 'grab',
          }}
        >
          {contentReady && (
            <div style={{ padding: '8px 10px', display: 'flex', flexDirection: 'column', gap: 6 }}>
              {/* 배지 + 요소명 + 시간(오른쪽 상단) */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 7 }}>
                <div style={{
                  width: 22, height: 22, borderRadius: '50%',
                  background: SPEC_COLOR, flexShrink: 0,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                }}>
                  <span style={{ fontSize: 10, fontWeight: 700, color: '#fff', lineHeight: 1 }}>{num}</span>
                </div>
                <span style={{
                  fontSize: 12, fontWeight: 600,
                  color: 'rgba(255,255,255,.88)',
                  overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                  fontFamily: FONT_FAMILY,
                  minWidth: 0, flexShrink: 1,
                }}>
                  {label}
                </span>
                {spec.updatedAt && (
                  <span style={{
                    marginLeft: 'auto',
                    flexShrink: 0,
                    fontSize: 9,
                    color: 'rgba(255,255,255,.28)',
                    whiteSpace: 'nowrap',
                    fontFamily: FONT_FAMILY,
                  }}>
                    {timeAgo(spec.updatedAt)}
                  </span>
                )}
              </div>

              {/* 스펙 내용 미리보기 */}
              {spec.content && (
                <div style={{
                  fontSize: 11, color: 'rgba(255,255,255,.55)',
                  lineHeight: 1.55,
                  display: '-webkit-box',
                  WebkitLineClamp: 3,
                  WebkitBoxOrient: 'vertical',
                  overflow: 'hidden',
                  fontFamily: FONT_FAMILY,
                }}>
                  {spec.content}
                </div>
              )}
            </div>
          )}
        </div>,
        document.body
      )}
    </>
  )
}
