const GA_ENDPOINT = 'https://www.google-analytics.com/mp/collect'
const MEASUREMENT_ID = 'G-64Z1HHSLK0'
const API_SECRET = 'tb0d3RSUTpaHJxHi1eo79w'
const CID_KEY = 'sb_ga_cid'

let _serviceId: string | undefined

export function setServiceId(id: string): void {
  _serviceId = id
}

function getClientId(): string {
  try {
    let cid = localStorage.getItem(CID_KEY)
    if (!cid) {
      cid = `${Math.random().toString(36).slice(2, 10)}.${Date.now()}`
      localStorage.setItem(CID_KEY, cid)
    }
    return cid
  } catch {
    return `anon.${Date.now()}`
  }
}

export function trackEvent(name: string, params: Record<string, unknown> = {}): void {
  try {
    const enriched = _serviceId ? { service_id: _serviceId, ...params } : params
    // window.gtag 우선 (specbridge-init.js 로드 시 설정) — 동일 client_id로 세션 연결
    const g = (window as unknown as { gtag?: (...args: unknown[]) => void }).gtag
    if (typeof g === 'function') {
      g('event', name, enriched)
      return
    }
    // Fallback: GA4 Measurement Protocol
    fetch(`${GA_ENDPOINT}?measurement_id=${MEASUREMENT_ID}&api_secret=${API_SECRET}`, {
      method: 'POST',
      body: JSON.stringify({
        client_id: getClientId(),
        events: [{ name, params: enriched }],
      }),
      keepalive: true,
    }).catch(() => {})
  } catch {
    // silent fail
  }
}
