import React, { useEffect, useState, type ReactNode } from 'react'
import { FONT_FAMILY } from './constants'

// ── SpecBridge 로고 SVG (viewBox 확장으로 클리핑 없음) ──────────────────────
const SB_LOGO_PATHS = (
  <>
    <path opacity="0.69" d="M111.309 79.6218C116.002 96.9372 100.191 112.84 82.8489 108.247L21.3533 91.961C4.01096 87.3681 -1.85607 65.7239 10.7927 53.0015L55.6448 7.88791C68.2936 -4.83456 89.9715 0.906559 94.6651 18.2219L111.309 79.6218Z" fill="#3078FF"/>
    <path opacity="0.5" d="M101.327 142.828C86.0562 152.245 66.3188 141.599 65.7993 123.666L64.723 86.5136C64.2035 68.5809 83.2915 56.8106 99.0814 65.3271L131.795 82.9713C147.585 91.4877 148.234 113.904 132.964 123.32L101.327 142.828Z" fill="#4CD3FF"/>
  </>
)
// viewBox는 실제 패스 범위(-10,-10)~(158,162)로 확장 — 클리핑 없음
const SB_LOGO_VIEWBOX = '-10 -10 170 172'

// ── 가이드 스텝 라인 아이콘 ──────────────────────────────────────────────────
const GIcon = ({ children, size = 32 }: { children: React.ReactNode; size?: number }) => (
  <div style={{ display: 'flex', justifyContent: 'center' }}>
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.75)" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round">
      {children}
    </svg>
  </div>
)

/** 인트로 카드용 풀 로고 — 인라인 SVG (클리핑 없음) */
function IntroLogo() {
  return (
    <svg width={54} height={54} viewBox={SB_LOGO_VIEWBOX} fill="none" style={{ display: 'block', margin: '0 auto', position: 'relative', left: -3 }}>
      {SB_LOGO_PATHS}
    </svg>
  )
}

const GUIDE_KEY = 'cs_annot_guide_v1'

export function hasDismissedForever(): boolean {
  try { return localStorage.getItem(GUIDE_KEY) === '1' } catch { return false }
}
function markDismissedForever(): void {
  try { localStorage.setItem(GUIDE_KEY, '1') } catch { /* ignore */ }
}

// ── Steps ──────────────────────────────────────────────────────────────────
interface Step {
  icon: ReactNode
  title: string
  badge: string
  desc: string
  /** data-guide 속성값 (null = 전체 딤만) */
  target: string | null
}

const STEPS: Step[] = [
  {
    icon: <IntroLogo />,
    title: 'SpecBridge',
    badge: '화면 스펙 협업 툴',
    desc: '스펙브릿지는 화면 요소 별 스펙을 정의하고,\n핀으로 코멘트·검토를 팀원과 함께 관리하는 협업 툴입니다.\n아래 가이드로 핵심 기능을 살펴보세요.',
    target: null,
  },
  {
    icon: <GIcon><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></GIcon>,
    title: '이름 설정',
    badge: '기본 설정',
    desc: '우측 툴바의 설정(⚙) 버튼을 클릭해 이름을 입력하세요.\n핀과 스펙에 작성자 정보가 표시됩니다.',
    target: 'sb-settings',
  },
  {
    icon: <GIcon><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></GIcon>,
    title: '설계 모드',
    badge: '기본 설정',
    desc: '설계 모드 버튼으로 스펙 작업을 ON/OFF할 수 있습니다.\n설계 모드에서만 핀 추가·스펙 편집이 가능합니다.\n단축키 A',
    target: 'sb-design-mode',
  },
  {
    icon: <GIcon><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="9" y1="13" x2="15" y2="13"/><line x1="9" y1="17" x2="13" y2="17"/></GIcon>,
    title: '스펙 추가',
    badge: '스펙 관리',
    desc: '설계 모드에서 "스펙 추가" 버튼으로\n화면 요소를 클릭해 스펙을 등록합니다.\n우측 패널에서 내용을 편집할 수 있습니다.\n단축키 S',
    target: 'sb-add-spec',
  },
  {
    icon: <GIcon><path d="m3 21 1.9-5.7a8.5 8.5 0 1 1 3.8 3.8z"/></GIcon>,
    title: '코멘트 추가',
    badge: '협업',
    desc: '핀 추가 버튼으로 화면의 원하는 위치에 핀을 찍고\n코멘트를 남기세요.\n핀을 클릭하면 스레드 댓글·해결 처리가 가능합니다.\n단축키 C',
    target: 'sb-add-pin',
  },
  {
    icon: <GIcon><rect width="18" height="14" x="3" y="4" rx="2"/><path d="M3 10h18"/><path d="M8 20h8M12 14v6"/></GIcon>,
    title: '레이아웃 전환',
    badge: '화면 설정',
    desc: '로고 오른쪽의 뷰포트 아이콘으로\nPC · 태블릿 · 모바일 레이아웃을 전환할 수 있습니다.\n설정(⚙) 버튼에서 패널 표시 방식도 변경할 수 있습니다.',
    target: 'sb-viewport',
  },
  {
    icon: <GIcon><rect width="20" height="16" x="2" y="4" rx="2"/><path d="M6 8h.001M10 8h.001M14 8h.001M18 8h.001M8 12h.001M12 12h.001M16 12h.001M7 16h10"/></GIcon>,
    title: '단축키 안내',
    badge: '단축키',
    desc: '[A] 설계 모드 ON/OFF\n[C] 코멘트 추가\n[S] 스펙 추가\n[L] 목록',
    target: null,
  },
]

const SPOTLIGHT_PADDING = 8

interface SpotRect { top: number; left: number; width: number; height: number }

function getSpotRect(target: string | null): SpotRect | null {
  if (!target) return null
  const el = document.querySelector(`[data-guide="${target}"]`)
  if (!el) return null
  const r = el.getBoundingClientRect()
  return { top: r.top, left: r.left, width: r.width, height: r.height }
}

interface Props {
  onClose: (forever: boolean) => void
}

export function OnboardingGuide({ onClose }: Props) {
  const [step, setStep] = useState(0)
  const [hideForever, setHideForever] = useState(false)
  const [spotRect, setSpotRect] = useState<SpotRect | null>(null)
  const isLast = step === STEPS.length - 1
  const current = STEPS[step]

  // 스텝 변경 시 타겟 엘리먼트 위치 계산
  useEffect(() => {
    // requestAnimationFrame으로 DOM 렌더 후 측정
    const raf = requestAnimationFrame(() => {
      setSpotRect(getSpotRect(current.target))
    })
    return () => cancelAnimationFrame(raf)
  }, [step, current.target])

  // 윈도우 리사이즈 시 재계산
  useEffect(() => {
    const onResize = () => setSpotRect(getSpotRect(current.target))
    window.addEventListener('resize', onResize)
    return () => window.removeEventListener('resize', onResize)
  }, [current.target])

  const handleClose = () => {
    if (hideForever) markDismissedForever()
    onClose(hideForever)
  }

  const handleNext = () => {
    if (isLast) { handleClose(); return }
    setStep((v) => v + 1)
  }

  const handlePrev = () => setStep((v) => v - 1)

  return (
    <>
      {/* ── 클릭 오버레이 (딤 or 투명) ── */}
      <div
        onClick={handleClose}
        style={{
          position: 'fixed',
          inset: 0,
          zIndex: 19996,
          background: spotRect ? 'transparent' : 'rgba(0,0,0,.70)',
          fontFamily: FONT_FAMILY,
        }}
      />

      {/* ── 스포트라이트 링 ── */}
      {spotRect && (
        <div
          style={{
            position: 'fixed',
            top: spotRect.top - SPOTLIGHT_PADDING,
            left: spotRect.left - SPOTLIGHT_PADDING,
            width: spotRect.width + SPOTLIGHT_PADDING * 2,
            height: spotRect.height + SPOTLIGHT_PADDING * 2,
            borderRadius: 10,
            boxShadow: '0 0 0 9999px rgba(0,0,0,.70)',
            border: '2px solid rgba(59,130,246,.75)',
            zIndex: 19997,
            transition: 'top .3s cubic-bezier(.4,0,.2,1), left .3s cubic-bezier(.4,0,.2,1), width .3s cubic-bezier(.4,0,.2,1), height .3s cubic-bezier(.4,0,.2,1)',
            pointerEvents: 'none',
          }}
        />
      )}

      {/* ── 가이드 카드 (중앙 고정) ── */}
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          position: 'fixed',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          zIndex: 19999,
          background: 'rgba(12,12,12,.98)',
          border: '1px solid rgba(255,255,255,.1)',
          borderRadius: 16,
          padding: '20px 26px 18px',
          width: 340,
          height: 390,
          maxHeight: 'calc(100vh - 48px)',
          display: 'flex',
          flexDirection: 'column',
          overflowY: 'auto',
          boxShadow: '0 32px 80px rgba(0,0,0,.75)',
          fontFamily: FONT_FAMILY,
        }}
      >
        {/* 닫기 버튼 */}
        <button
          onClick={handleClose}
          style={{
            position: 'absolute', top: 13, right: 14,
            background: 'transparent', border: 'none',
            color: 'rgba(255,255,255,.28)', fontSize: 15,
            cursor: 'pointer', lineHeight: 1, padding: 4,
          }}
        >✕</button>

        {/* 스텝 인디케이터 */}
        <div style={{ display: 'flex', gap: 5, justifyContent: 'center', marginBottom: 14, flexShrink: 0 }}>
          {STEPS.map((_, i) => (
            <div
              key={i}
              onClick={() => setStep(i)}
              style={{
                width: i === step ? 20 : 6,
                height: 6,
                borderRadius: 3,
                background: i === step ? '#3B82F6' : 'rgba(255,255,255,.16)',
                cursor: 'pointer',
                transition: 'all .22s',
              }}
            />
          ))}
        </div>

        {/* 아이콘 */}
        <div style={{ height: 68, marginTop: 20, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
          {current.icon}
        </div>

        {/* 제목 */}
        <div style={{
          textAlign: 'center', fontSize: step === 0 ? 20 : 16, fontWeight: 700,
          color: 'rgba(255,255,255,.92)', marginBottom: 8, lineHeight: 1.3, flexShrink: 0,
        }}>
          {current.title}
        </div>
        {/* 카테고리 badge */}
        <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 8, flexShrink: 0 }}>
          {step === 0 ? (
            <span style={{
              fontSize: 10, fontWeight: 600, letterSpacing: '.6px',
              color: '#6B82F6', background: 'rgba(107,130,246,.15)',
              border: '1px solid rgba(107,130,246,.3)',
              borderRadius: 20, padding: '3px 10px',
              fontFamily: FONT_FAMILY,
            }}>{current.badge}</span>
          ) : (
            <span style={{
              fontSize: 10, fontWeight: 500, letterSpacing: '.4px',
              color: 'rgba(255,255,255,.28)', background: 'rgba(255,255,255,.06)',
              border: '1px solid rgba(255,255,255,.1)',
              borderRadius: 20, padding: '3px 10px',
              fontFamily: FONT_FAMILY,
            }}>{current.badge}</span>
          )}
        </div>

        {/* 설명 */}
        <div style={{
          flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center',
          textAlign: 'center', fontSize: 12.5, color: 'rgba(255,255,255,.48)',
          lineHeight: 1.75, whiteSpace: 'pre-line',
        }}>
          {current.desc}
        </div>

        {/* 스텝 표시 */}
        <div style={{ textAlign: 'center', fontSize: 10, color: 'rgba(255,255,255,.22)', marginBottom: 10, flexShrink: 0 }}>
          {step + 1} / {STEPS.length}
        </div>

        {/* 이전 / 다음 버튼 */}
        <div style={{ display: 'flex', gap: 8, marginBottom: 10, flexShrink: 0 }}>
          {step > 0 && (
            <button
              onClick={handlePrev}
              style={{
                flex: 1, padding: '9px 0', borderRadius: 8,
                background: 'transparent', border: '1px solid rgba(255,255,255,.1)',
                color: 'rgba(255,255,255,.4)', fontSize: 12, cursor: 'pointer',
                fontFamily: FONT_FAMILY,
              }}
            >이전</button>
          )}
          <button
            onClick={handleNext}
            style={{
              flex: 2, padding: '9px 0', borderRadius: 8,
              background: '#3B82F6', border: 'none',
              color: '#fff', fontSize: 12, fontWeight: 600,
              cursor: 'pointer', fontFamily: FONT_FAMILY,
              transition: 'background .15s',
            }}
            onMouseEnter={(e) => { e.currentTarget.style.background = '#2563EB' }}
            onMouseLeave={(e) => { e.currentTarget.style.background = '#3B82F6' }}
          >
            {isLast ? '시작하기 🚀' : '다음'}
          </button>
        </div>

        {/* 다시 보지 않음 */}
        <label
          style={{
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            gap: 7, cursor: 'pointer', userSelect: 'none', flexShrink: 0,
          }}
        >
          <input
            type="checkbox"
            checked={hideForever}
            onChange={(e) => setHideForever(e.target.checked)}
            style={{ width: 13, height: 13, cursor: 'pointer', accentColor: '#3B82F6' }}
          />
          <span style={{ fontSize: 11, color: 'rgba(255,255,255,.28)', fontFamily: FONT_FAMILY }}>
            앞으로 보이지 않음
          </span>
        </label>
      </div>
    </>
  )
}
