import { useCallback, useState } from 'react'
import type { MarkerAlign, PanelMode } from './types'

export interface SpecBridgeSettings {
  /** 패널 표시 방식: overlay = 콘텐츠 위에 떠 있음 / push = 콘텐츠를 오른쪽으로 밀어냄 */
  panelMode: PanelMode
  /** 핀 좌표 기준 정렬 방식 (전역) */
  markerAlign: MarkerAlign
}

const SETTINGS_KEY = 'cs_sb_settings_v1'

const DEFAULT_SETTINGS: SpecBridgeSettings = {
  panelMode: 'overlay',
  markerAlign: 'left',
}

function loadSettings(): SpecBridgeSettings {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY)
    if (raw) return { ...DEFAULT_SETTINGS, ...(JSON.parse(raw) as Partial<SpecBridgeSettings>) }
  } catch { /* ignore */ }
  return { ...DEFAULT_SETTINGS }
}

function saveSettings(settings: SpecBridgeSettings): void {
  try {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings))
  } catch { /* ignore */ }
}

export function useSettings() {
  const [settings, setSettingsState] = useState<SpecBridgeSettings>(loadSettings)

  const setSetting = useCallback(
    <K extends keyof SpecBridgeSettings>(key: K, value: SpecBridgeSettings[K]) => {
      setSettingsState((prev) => {
        const next = { ...prev, [key]: value }
        saveSettings(next)
        return next
      })
    },
    []
  )

  return { settings, setSetting }
}
