import React, { useEffect, useRef, useState } from 'react'
import { FALLBACK_LABEL_COLOR, FONT_FAMILY } from './constants'
import type { LabelDef } from './types'
import type { SpecBridgeSettings } from './useSettings'

interface Props {
  settings: SpecBridgeSettings
  onChangeSetting: <K extends keyof SpecBridgeSettings>(key: K, value: SpecBridgeSettings[K]) => void
  author: string
  labels: LabelDef[]
  onExportJson?: () => void
  onExportMarkdown?: () => void
  defaultLabelId: string | null
  onSaveAuthor: (name: string, labelId: string | null) => void
}

const IGear = () => (
  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="3"/>
    <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>
  </svg>
)

const IDownload = () => (
  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/>
  </svg>
)
const IZip = () => (
  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/>
    <line x1="12" y1="3" x2="12" y2="3"/><path d="M9 3h2v2H9zm2 2h2v2h-2zm-2 2h2v2H9z"/>
  </svg>
)

function ExportBtn({ label, icon, onClick }: { label: string; icon: React.ReactNode; onClick: () => void }) {
  return (
    <button
      onClick={onClick}
      style={{
        width: '100%', padding: '7px 0',
        border: '1px solid rgba(255,255,255,.12)', borderRadius: 3,
        background: 'transparent', color: 'rgba(255,255,255,.5)',
        fontSize: 11, cursor: 'pointer', fontFamily: FONT_FAMILY,
        display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
        transition: 'all .12s',
      }}
      onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,.07)'; e.currentTarget.style.color = 'rgba(255,255,255,.85)'; e.currentTarget.style.borderColor = 'rgba(255,255,255,.25)' }}
      onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = 'rgba(255,255,255,.5)'; e.currentTarget.style.borderColor = 'rgba(255,255,255,.12)' }}
    >
      {icon}{label}
    </button>
  )
}

function SectionTitle({ children }: { children: string }) {
  return (
    <div style={{ fontSize: 10, fontWeight: 700, color: 'rgba(255,255,255,.3)', letterSpacing: '.5px', textTransform: 'uppercase', marginBottom: 8, fontFamily: FONT_FAMILY }}>
      {children}
    </div>
  )
}

export function SettingsPopover({ settings, onChangeSetting, author, labels, defaultLabelId, onSaveAuthor, onExportJson, onExportMarkdown }: Props) {
  const [open, setOpen] = useState(false)
  const [nameInput, setNameInput] = useState(author)
  const [selectedLabelId, setSelectedLabelId] = useState<string | null>(defaultLabelId)
  const ref = useRef<HTMLDivElement>(null)

  // 팝오버 열릴 때 현재 값으로 초기화
  useEffect(() => {
    if (open) {
      setNameInput(author)
      setSelectedLabelId(defaultLabelId)
    }
  }, [open, author, defaultLabelId])

  // 외부 클릭 닫기
  useEffect(() => {
    if (!open) return
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [open])

  const handleSaveAuthor = () => {
    const trimmed = nameInput.trim()
    if (!trimmed) return
    onSaveAuthor(trimmed, selectedLabelId)
    setOpen(false)
  }

  const hasAuthorChange = nameInput.trim() !== author || selectedLabelId !== defaultLabelId

  return (
    <div ref={ref} data-sb-ui="true" style={{ position: 'relative', flexShrink: 0 }}>
      {/* 설정 버튼 */}
      <button
        onClick={() => setOpen((v) => !v)}
        title={author ? `설정 (작성자: ${author})` : '설정 — 작성자 미등록'}
        data-guide="sb-settings"
        style={{
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          width: 30, height: 26,
          border: `1px solid ${open ? 'rgba(255,255,255,.2)' : !author ? 'rgba(251,191,36,.4)' : 'rgba(255,255,255,.07)'}`,
          borderRadius: 2,
          background: open ? 'rgba(255,255,255,.1)' : !author ? 'rgba(251,191,36,.1)' : 'transparent',
          color: open ? 'rgba(255,255,255,.9)' : !author ? '#fbbf24' : 'rgba(255,255,255,.45)',
          cursor: 'pointer',
          transition: 'all .15s',
          flexShrink: 0,
          position: 'relative',
        }}
        onMouseEnter={(e) => {
          if (!open) {
            e.currentTarget.style.background = 'rgba(255,255,255,.07)'
            e.currentTarget.style.color = 'rgba(255,255,255,.8)'
            e.currentTarget.style.borderColor = 'rgba(255,255,255,.15)'
          }
        }}
        onMouseLeave={(e) => {
          if (!open) {
            e.currentTarget.style.background = !author ? 'rgba(251,191,36,.1)' : 'transparent'
            e.currentTarget.style.color = !author ? '#fbbf24' : 'rgba(255,255,255,.45)'
            e.currentTarget.style.borderColor = !author ? 'rgba(251,191,36,.4)' : 'rgba(255,255,255,.07)'
          }
        }}
      >
        <IGear />
        {/* 작성자 미등록 경고 배지 */}
        {!author && (
          <span style={{
            position: 'absolute', top: -4, right: -4,
            width: 8, height: 8, borderRadius: '50%',
            background: '#ef4444',
            border: '1.5px solid rgba(0,0,0,.8)',
          }} />
        )}
      </button>

      {/* 팝오버 */}
      {open && (
        <div
          style={{
            position: 'absolute',
            bottom: 'calc(100% + 8px)',
            right: 0,
            width: 240,
            background: 'rgba(10,10,10,.97)',
            backdropFilter: 'blur(24px)',
            WebkitBackdropFilter: 'blur(24px)',
            border: '1px solid rgba(255,255,255,.1)',
            borderRadius: 6,
            boxShadow: '0 -8px 40px rgba(0,0,0,.55)',
            zIndex: 20000,
            fontFamily: FONT_FAMILY,
            overflow: 'hidden',
          }}
        >
          {/* 헤더 */}
          <div style={{ padding: '10px 14px 8px', fontSize: 10, fontWeight: 700, color: 'rgba(255,255,255,.3)', letterSpacing: '.5px', textTransform: 'uppercase' }}>
            설정
          </div>
          <div style={{ height: 1, background: 'rgba(255,255,255,.07)' }} />

          {/* ── 작성자 섹션 ── */}
          <div style={{ padding: '12px 14px 0' }}>
            <SectionTitle>작성자</SectionTitle>

            {/* 이름 입력 */}
            <input
              value={nameInput}
              onChange={(e) => setNameInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter') handleSaveAuthor() }}
              placeholder="이름 입력..."
              style={{
                width: '100%', boxSizing: 'border-box',
                background: 'rgba(255,255,255,.06)',
                border: `1px solid ${!author ? 'rgba(251,191,36,.3)' : 'rgba(255,255,255,.12)'}`,
                borderRadius: 3, padding: '6px 9px',
                color: '#fff', fontSize: 12,
                fontFamily: FONT_FAMILY, outline: 'none',
                marginBottom: 8,
              }}
              onFocus={(e) => { e.currentTarget.style.borderColor = 'rgba(99,102,241,.5)' }}
              onBlur={(e) => { e.currentTarget.style.borderColor = !author ? 'rgba(251,191,36,.3)' : 'rgba(255,255,255,.12)' }}
            />

            {/* 기본 레이블 */}
            {labels.length > 0 && (
              <div style={{ marginBottom: 10 }}>
                <div style={{ fontSize: 10, color: 'rgba(255,255,255,.3)', marginBottom: 5, fontFamily: FONT_FAMILY }}>
                  기본 레이블
                </div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
                  {labels.map((l) => {
                    const color = l.color || FALLBACK_LABEL_COLOR
                    const active = selectedLabelId === l.id
                    return (
                      <button
                        key={l.id}
                        onClick={() => setSelectedLabelId(active ? null : l.id)}
                        style={{
                          display: 'flex', alignItems: 'center', gap: 4,
                          padding: '3px 8px', borderRadius: 3, fontSize: 11,
                          border: `1px solid ${active ? `${color}88` : 'rgba(255,255,255,.1)'}`,
                          background: active ? `${color}22` : 'transparent',
                          color: active ? color : 'rgba(255,255,255,.4)',
                          cursor: 'pointer', fontFamily: FONT_FAMILY, transition: 'all .12s',
                        }}
                        onMouseEnter={(e) => { if (!active) { e.currentTarget.style.borderColor = `${color}55`; e.currentTarget.style.color = color } }}
                        onMouseLeave={(e) => { if (!active) { e.currentTarget.style.borderColor = 'rgba(255,255,255,.1)'; e.currentTarget.style.color = 'rgba(255,255,255,.4)' } }}
                      >
                        <span style={{ width: 5, height: 5, borderRadius: '50%', background: color, flexShrink: 0 }} />
                        {l.name}
                      </button>
                    )
                  })}
                </div>
              </div>
            )}

            {/* 저장 버튼 */}
            <button
              onClick={handleSaveAuthor}
              disabled={!nameInput.trim() || !hasAuthorChange}
              style={{
                width: '100%', padding: '6px 0',
                border: 'none', borderRadius: 3,
                background: nameInput.trim() && hasAuthorChange ? 'rgba(99,102,241,.7)' : 'rgba(255,255,255,.07)',
                color: nameInput.trim() && hasAuthorChange ? '#fff' : 'rgba(255,255,255,.25)',
                fontSize: 11, fontWeight: 600,
                cursor: nameInput.trim() && hasAuthorChange ? 'pointer' : 'not-allowed',
                fontFamily: FONT_FAMILY, transition: 'all .12s',
                marginBottom: 12,
              }}
            >
              저장
            </button>
          </div>

          <div style={{ height: 1, background: 'rgba(255,255,255,.07)' }} />

          {/* ── 패널 표시 방식 ── */}
          <div style={{ padding: '12px 14px' }}>
            <SectionTitle>패널 표시 방식</SectionTitle>
            <div style={{ display: 'flex', gap: 5 }}>
              {([
                { mode: 'overlay' as const, label: '오버레이', desc: '위에 표시' },
                { mode: 'push'    as const, label: '밀기',     desc: '콘텐츠 이동' },
              ] as const).map(({ mode, label, desc }) => {
                const active = settings.panelMode === mode
                return (
                  <button
                    key={mode}
                    onClick={() => onChangeSetting('panelMode', mode)}
                    style={{
                      flex: 1, padding: '6px 0',
                      border: `1px solid ${active ? 'rgba(59,130,246,.5)' : 'rgba(255,255,255,.12)'}`,
                      borderRadius: 3,
                      background: active ? 'rgba(59,130,246,.18)' : 'transparent',
                      color: active ? '#60a5fa' : 'rgba(255,255,255,.45)',
                      fontSize: 11, fontWeight: active ? 600 : 400,
                      cursor: 'pointer', fontFamily: FONT_FAMILY,
                      transition: 'all .12s', textAlign: 'center',
                    }}
                    onMouseEnter={(e) => { if (!active) { e.currentTarget.style.borderColor = 'rgba(255,255,255,.25)'; e.currentTarget.style.color = 'rgba(255,255,255,.75)' } }}
                    onMouseLeave={(e) => { if (!active) { e.currentTarget.style.borderColor = 'rgba(255,255,255,.12)'; e.currentTarget.style.color = 'rgba(255,255,255,.45)' } }}
                  >
                    <div>{label}</div>
                    <div style={{ fontSize: 9, color: active ? 'rgba(96,165,250,.6)' : 'rgba(255,255,255,.2)', marginTop: 2 }}>{desc}</div>
                  </button>
                )
              })}
            </div>
          </div>

          {/* ── 화면 마커 기준 ── */}
          <div style={{ height: 1, background: 'rgba(255,255,255,.07)' }} />
          <div style={{ padding: '12px 14px' }}>
            <SectionTitle>화면 마커 기준</SectionTitle>
            <div style={{ display: 'flex', gap: 5 }}>
              {([
                { align: 'left'   as const, label: '왼쪽' },
                { align: 'center' as const, label: '중앙' },
                { align: 'right'  as const, label: '오른쪽' },
              ] as const).map(({ align, label }) => {
                const active = settings.markerAlign === align
                return (
                  <button
                    key={align}
                    onClick={() => onChangeSetting('markerAlign', align)}
                    style={{
                      flex: 1, padding: '6px 0',
                      border: `1px solid ${active ? 'rgba(59,130,246,.5)' : 'rgba(255,255,255,.12)'}`,
                      borderRadius: 3,
                      background: active ? 'rgba(59,130,246,.18)' : 'transparent',
                      color: active ? '#60a5fa' : 'rgba(255,255,255,.45)',
                      fontSize: 11, fontWeight: active ? 600 : 400,
                      cursor: 'pointer', fontFamily: FONT_FAMILY,
                      transition: 'all .12s', textAlign: 'center',
                    }}
                    onMouseEnter={(e) => { if (!active) { e.currentTarget.style.borderColor = 'rgba(255,255,255,.25)'; e.currentTarget.style.color = 'rgba(255,255,255,.75)' } }}
                    onMouseLeave={(e) => { if (!active) { e.currentTarget.style.borderColor = 'rgba(255,255,255,.12)'; e.currentTarget.style.color = 'rgba(255,255,255,.45)' } }}
                  >
                    {label}
                  </button>
                )
              })}
            </div>
          </div>

          {/* 스펙 내보내기 */}
          {(onExportJson || onExportMarkdown) && (
            <>
              <div style={{ height: 1, background: 'rgba(255,255,255,.07)', margin: '2px 0 10px' }} />
              <div style={{ padding: '0 14px 10px', display: 'flex', flexDirection: 'column', gap: 6 }}>
                {onExportJson && (
                  <ExportBtn
                    label="스펙 내보내기 (JSON)"
                    icon={<IDownload />}
                    onClick={() => { onExportJson(); setOpen(false) }}
                  />
                )}
                {onExportMarkdown && (
                  <ExportBtn
                    label="스펙 내보내기 (MD · ZIP)"
                    icon={<IZip />}
                    onClick={() => { onExportMarkdown(); setOpen(false) }}
                  />
                )}
              </div>
            </>
          )}
        </div>
      )}
    </div>
  )
}
