function fmtDate(iso: string): string {
  const d = new Date(iso)
  const mm = String(d.getMonth() + 1).padStart(2, '0')
  const dd = String(d.getDate()).padStart(2, '0')
  const hh = String(d.getHours()).padStart(2, '0')
  const mi = String(d.getMinutes()).padStart(2, '0')
  return `${mm}.${dd} ${hh}:${mi}`
}

function fmtDateOnly(iso: string): string {
  const d = new Date(iso)
  const yy = d.getFullYear()
  const mm = String(d.getMonth() + 1).padStart(2, '0')
  const dd = String(d.getDate()).padStart(2, '0')
  return `${yy}.${mm}.${dd}`
}

function todayIso(): string {
  const d = new Date()
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
}

// ── 공용 UI ────────────────────────────────────────────────────────────────────

function StatusPill({ status, onChange }: { status: SpecStatus; onChange?: (s: SpecStatus) => void }) {
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLDivElement>(null)
  const cfg = STATUS_CFG[status] ?? STATUS_CFG.draft

  useEffect(() => {
    if (!open) return
    const h = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false) }
    document.addEventListener('mousedown', h)
    return () => document.removeEventListener('mousedown', h)
  }, [open])

  return (
    <div ref={ref} style={{ position: 'relative', display: 'inline-block' }}>
      <button
        onClick={() => onChange && setOpen(v => !v)}
        style={{
          padding: '1px 7px', borderRadius: 2, fontSize: 9, fontWeight: 700,
          border: `1px solid ${cfg.color}44`,
          background: `${cfg.color}18`, color: cfg.color,
          cursor: onChange ? 'pointer' : 'default', fontFamily: FONT_FAMILY,
        }}
      >{cfg.label}</button>
      {open && onChange && (
        <div style={{
          position: 'absolute', top: 'calc(100% + 4px)', right: 0, zIndex: 100,
          background: DARK.bg2, border: `1px solid ${DARK.brd}`,
          borderRadius: 3, overflow: 'hidden', minWidth: 110,
          boxShadow: '0 8px 24px rgba(0,0,0,.5)',
        }}>
          {ALL_STATUSES.map(s => {
            const c = STATUS_CFG[s]
            return (
              <button key={s} onClick={() => { onChange(s); setOpen(false) }} style={{
                display: 'block', width: '100%', textAlign: 'left',
                padding: '7px 12px', background: 'transparent', border: 'none',
                color: c.color, fontSize: 11, cursor: 'pointer', fontFamily: FONT_FAMILY, fontWeight: 600,
              }}
              onMouseEnter={e => { e.currentTarget.style.background = DARK.bg3 }}
              onMouseLeave={e => { e.currentTarget.style.background = 'transparent' }}
              >{c.label}</button>
            )
          })}
        </div>
      )}
    </div>
  )
}

// ── 화면 셀렉터 ────────────────────────────────────────────────────────────────

function ScreenSelector({ screens, currentPageId, onSelect }: {
  screens: ScreenSpec[]
  currentPageId: string
  onSelect: (pageId: string) => void
}) {
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLDivElement>(null)
  const current = screens.find(s => s.pageId === currentPageId)

  useEffect(() => {
    if (!open) return
    const h = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false) }
    document.addEventListener('mousedown', h)
    return () => document.removeEventListener('mousedown', h)
  }, [open])

  if (screens.length <= 1) return (
    <span style={{ fontSize: 11, fontWeight: 700, color: DARK.txt, fontFamily: FONT_FAMILY }}>
      {current?.title || currentPageId}
    </span>
  )

  return (
    <div ref={ref} style={{ position: 'relative' }}>
      <button onClick={() => setOpen(v => !v)} style={{
        display: 'flex', alignItems: 'center', gap: 4,
        background: DARK.bg3, border: `1px solid ${DARK.brd}`,
        borderRadius: 2, padding: '3px 8px', cursor: 'pointer',
        color: DARK.txt, fontSize: 11, fontWeight: 700, fontFamily: FONT_FAMILY,
      }}>
        <span style={{ maxWidth: 130, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
          {current?.title || currentPageId}
        </span>
        <span style={{ fontSize: 7, opacity: .5 }}>▾</span>
      </button>
      {open && (
        <div style={{
          position: 'absolute', top: 'calc(100% + 4px)', left: 0, zIndex: 100,
          background: DARK.bg2, border: `1px solid ${DARK.brd}`,
          borderRadius: 3, overflow: 'hidden', minWidth: 180,
          boxShadow: '0 8px 24px rgba(0,0,0,.5)',
        }}>
          {screens.map(s => (
            <button key={s.pageId} onClick={() => { onSelect(s.pageId); setOpen(false) }} style={{
              display: 'block', width: '100%', textAlign: 'left',
              padding: '8px 12px', border: 'none',
              background: s.pageId === currentPageId ? `${SPEC_COLOR}18` : 'transparent',
              color: s.pageId === currentPageId ? SPEC_COLOR : DARK.txS,
              fontSize: 11, cursor: 'pointer', fontFamily: FONT_FAMILY,
              fontWeight: s.pageId === currentPageId ? 700 : 400,
            }}
            onMouseEnter={e => { if (s.pageId !== currentPageId) e.currentTarget.style.background = DARK.bg3 }}
            onMouseLeave={e => { if (s.pageId !== currentPageId) e.currentTarget.style.background = 'transparent' }}
            >{s.title || s.pageId}</button>
          ))}
        </div>
      )}
    </div>
  )
}

// ── 변경 이력 — 단일 엔트리 카드 ─────────────────────────────────────────────

function ChangelogEntryCard({ entry, canDelete, onDelete, isLast }: {
  entry: ChangelogEntry
  canDelete: boolean
  onDelete: () => void
  isLast: boolean
}) {
  const [hovered, setHovered] = useState(false)
  const [confirming, setConfirming] = useState(false)
  return (
    <div
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => { setHovered(false); setConfirming(false) }}
      style={{
        padding: '8px 14px',
        borderBottom: isLast ? 'none' : '1px solid rgba(255,255,255,.05)',
        background: confirming ? 'rgba(239,68,68,.06)' : hovered ? 'rgba(255,255,255,.02)' : 'transparent',
        transition: 'background .1s',
      }}
    >
      {/* 버전 뱃지 | 날짜 | 작성자 | 삭제 버튼 */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 5, marginBottom: 3 }}>
        {entry.version && (() => {
          const idx = (entry.seq > 0 ? entry.seq - 1 : 0) % 10
          const c = CHANGELOG_COLORS[idx]
          return (
            <span style={{
              fontSize: 9, fontWeight: 700, fontFamily: FONT_FAMILY,
              padding: '1px 6px', borderRadius: 3, flexShrink: 0,
              background: c.bg, color: c.fg, border: `1px solid ${c.bd}`,
            }}>
              {entry.version}
            </span>
          )
        })()}
        <span style={{ fontSize: 9, color: 'rgba(255,255,255,.28)', fontFamily: FONT_FAMILY }}>
          {fmtDateOnly(entry.createdAt)}
        </span>
        <span style={{ flex: 1 }} />
        {entry.author && !confirming && (
          <span style={{ fontSize: 9, color: 'rgba(255,255,255,.28)', fontFamily: FONT_FAMILY }}>
            {entry.author}
          </span>
        )}
        {canDelete && !confirming && (
          <button
            onClick={() => setConfirming(true)}
            title="삭제"
            style={{
              opacity: hovered ? 1 : 0, transition: 'opacity .15s',
              background: 'transparent', border: 'none',
              color: 'rgba(255,255,255,.4)', cursor: 'pointer',
              fontSize: 11, lineHeight: 1, padding: '0 2px',
              fontFamily: FONT_FAMILY,
            }}
            onMouseEnter={e => { e.currentTarget.style.color = '#f87171' }}
            onMouseLeave={e => { e.currentTarget.style.color = 'rgba(255,255,255,.4)' }}
          >×</button>
        )}
        {confirming && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
            <span style={{ fontSize: 9, color: 'rgba(255,255,255,.45)', fontFamily: FONT_FAMILY }}>삭제할까요?</span>
            <button
              onClick={onDelete}
              style={{
                fontSize: 9, fontWeight: 700, padding: '2px 8px', borderRadius: 3, cursor: 'pointer',
                background: 'rgba(239,68,68,.25)', border: '1px solid rgba(239,68,68,.4)',
                color: '#fca5a5', fontFamily: FONT_FAMILY,
              }}
            >삭제</button>
            <button
              onClick={() => setConfirming(false)}
              style={{
                fontSize: 9, padding: '2px 8px', borderRadius: 3, cursor: 'pointer',
                background: 'transparent', border: '1px solid rgba(255,255,255,.15)',
                color: 'rgba(255,255,255,.45)', fontFamily: FONT_FAMILY,
              }}
            >취소</button>
          </div>
        )}
      </div>
      {/* 내용 */}
      <div style={{
        fontSize: 11, color: 'rgba(255,255,255,.6)', fontFamily: FONT_FAMILY,
        lineHeight: 1.55, whiteSpace: 'pre-wrap', wordBreak: 'break-word',
      }}>
        {entry.content}
      </div>
    </div>
  )
}

// ── 변경 이력 섹션 ────────────────────────────────────────────────────────────

const INPUT_STYLE: import('react').CSSProperties = {
  width: '100%', boxSizing: 'border-box',
  background: DARK.bg3, border: `1px solid rgba(255,255,255,.12)`,
  borderRadius: 3, padding: '5px 8px',
  color: DARK.txt, fontSize: 11, fontFamily: FONT_FAMILY,
  outline: 'none',
}

function ChangelogSection({ storage, currentAuthor }: {
  storage: StorageAdapter
  currentAuthor: string
}) {
  const [entries, setEntries] = useState<ChangelogEntry[]>([])
  const [open, setOpen] = useState(false)
  const [adding, setAdding] = useState(false)
  const [formDate, setFormDate] = useState('')
  const [formVersion, setFormVersion] = useState('')
  const [formContent, setFormContent] = useState('')
  const [formAuthor, setFormAuthor] = useState('')
  const [saving, setSaving] = useState(false)
  const [saveError, setSaveError] = useState<string | null>(null)

  useEffect(() => {
    if (!storage.loadChangelog) return
    storage.loadChangelog()
      .then(e => { setEntries(e) })
      .catch(() => {})
  }, [storage])

  const openForm = () => {
    setFormDate(todayIso())
    setFormVersion('')
    setFormContent('')
    setFormAuthor(currentAuthor || '')
    setSaveError(null)
    setAdding(true)
    setOpen(true)
  }

  const closeForm = () => {
    setAdding(false)
    setSaveError(null)
  }

  const handleAdd = async () => {
    if (!formContent.trim() || !storage.addChangelogEntry) return
    setSaving(true)
    setSaveError(null)
    try {
      const entry = await storage.addChangelogEntry(
        formContent.trim(),
        formAuthor.trim() || null,
        formDate || null,
        formVersion.trim() || null
      )
      setEntries(prev => [entry, ...prev])
      closeForm()
      setOpen(true)
    } catch (e) {
      console.error('[SpecBridge] changelog save error:', e)
      setSaveError(e instanceof Error ? e.message : String(e) || '저장에 실패했습니다')
    } finally {
      setSaving(false)
    }
  }

  const handleDelete = async (id: string) => {
    if (!storage.deleteChangelogEntry) return
    try {
      await storage.deleteChangelogEntry(id)
      setEntries(prev => prev.filter(e => e.id !== id))
    } catch { /* ignore */ }
  }

  if (!storage.loadChangelog) return null

  return (
    <div style={{ flexShrink: 0, borderTop: '1px solid rgba(255,255,255,.08)' }}>

      {/* 헤더 행 */}
      <div style={{ display: 'flex', alignItems: 'center', padding: '9px 14px 8px', gap: 6 }}>
        <button
          onClick={() => setOpen(v => !v)}
          style={{ flex: 1, display: 'flex', alignItems: 'center', gap: 5, background: 'transparent', border: 'none', cursor: 'pointer', padding: 0, textAlign: 'left', minWidth: 0 }}
        >
          {entries.length > 0 ? (
            <>
              {entries[0].version && (() => {
                const idx = (entries[0].seq > 0 ? entries[0].seq - 1 : 0) % 10
                const c = CHANGELOG_COLORS[idx]
                return (
                  <span style={{
                    fontSize: 10, fontWeight: 700, fontFamily: FONT_FAMILY, flexShrink: 0,
                    padding: '1px 6px', borderRadius: 3,
                    background: c.bg, color: c.fg, border: `1px solid ${c.bd}`,
                  }}>
                    {entries[0].version}
                  </span>
                )
              })()}
              <span style={{ fontSize: 10, color: 'rgba(255,255,255,.45)', fontFamily: FONT_FAMILY, flexShrink: 0 }}>
                {fmtDateOnly(entries[0].createdAt)}
              </span>
            </>
          ) : (
            <span style={{ fontSize: 10, fontWeight: 700, color: 'rgba(255,255,255,.4)', textTransform: 'uppercase', letterSpacing: '.4px', fontFamily: FONT_FAMILY }}>
              변경 이력
            </span>
          )}
          <span style={{ fontSize: 8, color: 'rgba(255,255,255,.22)', marginLeft: 2 }}>{open ? '▲' : '▼'}</span>
        </button>
        {storage.addChangelogEntry && (
          <button
            onClick={() => adding ? closeForm() : openForm()}
            title={adding ? '입력 취소' : '이력 추가'}
            style={{
              width: 20, height: 20, borderRadius: 3, fontSize: 14, lineHeight: 1,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              background: adding ? `${SPEC_COLOR}22` : 'transparent',
              border: `1px solid ${adding ? SPEC_COLOR : 'rgba(255,255,255,.12)'}`,
              color: adding ? SPEC_COLOR : 'rgba(255,255,255,.4)',
              cursor: 'pointer', transition: 'all .15s',
            }}
            onMouseEnter={e => { if (!adding) { e.currentTarget.style.borderColor = SPEC_COLOR; e.currentTarget.style.color = SPEC_COLOR } }}
            onMouseLeave={e => { if (!adding) { e.currentTarget.style.borderColor = 'rgba(255,255,255,.12)'; e.currentTarget.style.color = 'rgba(255,255,255,.4)' } }}
          >{adding ? '×' : '+'}</button>
        )}
      </div>

      {/* 이력 추가 폼 */}
      {adding && (
        <div style={{ padding: '0 12px 12px', display: 'flex', flexDirection: 'column', gap: 6 }}>
          {/* 버전 | 날짜 | 작성자 (1:1:1) */}
          <div style={{ display: 'flex', gap: 6 }}>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 9, color: 'rgba(255,255,255,.35)', fontFamily: FONT_FAMILY, marginBottom: 3 }}>버전</div>
              <input
                type="text"
                value={formVersion}
                onChange={e => setFormVersion(e.target.value)}
                placeholder="v1.0.0"
                style={INPUT_STYLE}
              />
            </div>
            <div style={{ flex: 2, minWidth: 0 }}>
              <div style={{ fontSize: 9, color: 'rgba(255,255,255,.35)', fontFamily: FONT_FAMILY, marginBottom: 3 }}>날짜</div>
              <input
                type="date"
                value={formDate}
                onChange={e => setFormDate(e.target.value)}
                style={{ ...INPUT_STYLE, colorScheme: 'dark' }}
              />
            </div>
            <div style={{ flex: 2, minWidth: 0 }}>
              <div style={{ fontSize: 9, color: 'rgba(255,255,255,.35)', fontFamily: FONT_FAMILY, marginBottom: 3 }}>작성자</div>
              <input
                type="text"
                value={formAuthor}
                onChange={e => setFormAuthor(e.target.value)}
                placeholder="작성자"
                style={INPUT_STYLE}
              />
            </div>
          </div>
          {/* 변경 내용 */}
          <div>
            <div style={{ fontSize: 9, color: 'rgba(255,255,255,.35)', fontFamily: FONT_FAMILY, marginBottom: 3 }}>변경 내용</div>
            <textarea
              autoFocus
              value={formContent}
              onChange={e => setFormContent(e.target.value)}
              placeholder="변경된 내용을 입력하세요…"
              rows={3}
              onKeyDown={e => {
                if (e.key === 'Escape') { e.nativeEvent.stopImmediatePropagation(); closeForm() }
                if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); handleAdd() }
              }}
              style={{ ...INPUT_STYLE, resize: 'none', lineHeight: 1.6, overflow: 'hidden', border: `1px solid ${SPEC_COLOR}55` }}
            />
          </div>
          {/* 에러 메시지 */}
          {saveError && (
            <div style={{ fontSize: 10, color: '#f87171', fontFamily: FONT_FAMILY, background: 'rgba(239,68,68,.1)', borderRadius: 3, padding: '4px 8px' }}>
              ⚠ {saveError}
            </div>
          )}
          {/* 버튼 행 */}
          <div style={{ display: 'flex', gap: 5, justifyContent: 'flex-end' }}>
            <button
              onClick={closeForm}
              style={{ padding: '3px 10px', borderRadius: 3, fontSize: 10, background: 'transparent', border: `1px solid ${DARK.brd}`, color: DARK.txS, cursor: 'pointer', fontFamily: FONT_FAMILY }}
            >취소</button>
            <button
              onClick={handleAdd}
              disabled={!formContent.trim() || saving}
              style={{ padding: '3px 10px', borderRadius: 3, fontSize: 10, fontWeight: 600, background: SPEC_COLOR, border: 'none', color: '#fff', cursor: 'pointer', fontFamily: FONT_FAMILY, opacity: !formContent.trim() || saving ? 0.5 : 1 }}
            >{saving ? '저장 중…' : '저장'}</button>
          </div>
        </div>
      )}

      {/* 이력 목록 */}
      {open && (
        <div className="sb-scroll" style={{ maxHeight: 220, overflowY: 'auto' }}>
          {entries.length === 0 ? (
            <div style={{ padding: '4px 14px 12px', fontSize: 11, color: 'rgba(255,255,255,.2)', fontFamily: FONT_FAMILY }}>
              변경 이력이 없습니다.
            </div>
          ) : entries.map((entry, idx) => (
            <ChangelogEntryCard
              key={entry.id}
              entry={entry}
              canDelete={!!storage.deleteChangelogEntry}
              onDelete={() => handleDelete(entry.id)}
              isLast={idx === entries.length - 1}
            />
          ))}
        </div>
      )}
    </div>
  )
}

// ── 화면 목록 아이템 ──────────────────────────────────────────────────────────

function ScreenListItem({ s, isCurrent, cfg, canDelete, allAnnotations, onSelect, onDelete }: {
  s: ScreenSpec
  isCurrent: boolean
  cfg: { color: string; label: string }
  canDelete: boolean
  allAnnotations?: import('./types').PagePins
  onSelect: () => void
  onDelete: () => void
}) {
  const [hovered, setHovered] = useState(false)
  const [confirming, setConfirming] = useState(false)
  const pagePins = allAnnotations?.[s.pageId] ?? []
  const unresolvedCount = pagePins.filter(p => p.status !== 'resolved').length

  return (
    <div
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => { setHovered(false); setConfirming(false) }}
      style={{
        borderBottom: '1px solid rgba(255,255,255,.05)',
        background: confirming ? 'rgba(239,68,68,.06)' : isCurrent ? `${SPEC_COLOR}12` : hovered ? 'rgba(255,255,255,.04)' : 'transparent',
        transition: 'background .1s',
      }}
    >
      <button
        onClick={onSelect}
        style={{
          width: '100%', display: 'flex', flexDirection: 'column', gap: 4,
          padding: '12px 16px', background: 'transparent',
          border: 'none', cursor: 'pointer', textAlign: 'left',
        }}
      >
        {/* 행 1: 제목 | 업데이트일 | × 버튼 */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <span style={{
            flex: 1, fontSize: 12, fontWeight: isCurrent ? 700 : 500,
            color: isCurrent ? SPEC_COLOR : s.status === 'deprecated' ? 'rgba(255,255,255,.3)' : 'rgba(255,255,255,.75)',
            overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
            fontFamily: FONT_FAMILY,
            textDecoration: s.status === 'deprecated' ? 'line-through' : 'none',
          }}>
            {s.title || s.pageId}
          </span>
          {s.updatedAt && !confirming && (
            <span style={{ fontSize: 9, color: 'rgba(255,255,255,.28)', flexShrink: 0, fontFamily: FONT_FAMILY }}>
              {fmtDate(s.updatedAt)}
            </span>
          )}
          {canDelete && !confirming && (
            <button
              onClick={e => { e.stopPropagation(); setConfirming(true) }}
              title="삭제"
              style={{
                opacity: hovered ? 1 : 0, transition: 'opacity .15s',
                background: 'transparent', border: 'none',
                color: 'rgba(255,255,255,.4)', cursor: 'pointer',
                fontSize: 13, lineHeight: 1, padding: '0 2px',
                fontFamily: FONT_FAMILY, flexShrink: 0,
              }}
              onMouseEnter={e => { e.currentTarget.style.color = '#f87171' }}
              onMouseLeave={e => { e.currentTarget.style.color = 'rgba(255,255,255,.4)' }}
            >×</button>
          )}
          {confirming && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 5 }} onClick={e => e.stopPropagation()}>
              <span style={{ fontSize: 9, color: 'rgba(255,255,255,.45)', fontFamily: FONT_FAMILY }}>삭제할까요?</span>
              <button
                onClick={e => { e.stopPropagation(); onDelete() }}
                style={{
                  fontSize: 9, fontWeight: 700, padding: '2px 8px', borderRadius: 3, cursor: 'pointer',
                  background: 'rgba(239,68,68,.25)', border: '1px solid rgba(239,68,68,.4)',
                  color: '#fca5a5', fontFamily: FONT_FAMILY,
                }}
              >삭제</button>
              <button
                onClick={e => { e.stopPropagation(); setConfirming(false) }}
                style={{
                  fontSize: 9, padding: '2px 8px', borderRadius: 3, cursor: 'pointer',
                  background: 'transparent', border: '1px solid rgba(255,255,255,.15)',
                  color: 'rgba(255,255,255,.45)', fontFamily: FONT_FAMILY,
                }}
              >취소</button>
            </div>
          )}
        </div>
        {/* 행 2: ● 상태 - 작성자 | 댓글수 */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <span style={{ fontSize: 11, color: cfg.color, flexShrink: 0 }}>●</span>
          <span style={{ fontSize: 10, fontWeight: 500, color: cfg.color, flexShrink: 0, fontFamily: FONT_FAMILY }}>
            {cfg.label}
          </span>
          {(s.updatedBy || s.createdBy) && (
            <>
              <span style={{ fontSize: 10, color: 'rgba(255,255,255,.2)', flexShrink: 0 }}>-</span>
              <span style={{
                fontSize: 10, color: 'rgba(255,255,255,.4)', fontFamily: FONT_FAMILY,
                overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', flex: 1,
              }}>
                {s.updatedBy || s.createdBy}
              </span>
            </>
          )}
          {!(s.updatedBy || s.createdBy) && <span style={{ flex: 1 }} />}
          {unresolvedCount > 0 && (
            <span style={{
              fontSize: 9, fontWeight: 700,
              color: '#93c5fd', background: 'rgba(59,130,246,.2)',
              padding: '1px 5px', borderRadius: 2,
              flexShrink: 0, fontFamily: FONT_FAMILY,
            }}>
              <IconChat size={9} color="#93c5fd"/> {unresolvedCount}
            </span>
          )}
        </div>
      </button>
    </div>
  )
}

// ── 화면 목록 패널 ────────────────────────────────────────────────────────────

function ScreenListPanel({ screens, currentPageId, onSelect, allAnnotations, storage, currentAuthor, onScreenAdded, onScreenDeleted, screensLoaded = true }: {
  screens: ScreenSpec[]
  currentPageId: string
  onSelect: (pageId: string) => void
  allAnnotations?: import('./types').PagePins
  storage: StorageAdapter
  currentAuthor: string
  onScreenAdded?: (screen: import('./types').ScreenSpec) => void
  onScreenDeleted?: (pageId: string) => void
  screensLoaded?: boolean
}) {
  const [filterStatus, setFilterStatus] = useState<SpecStatus | null>(null)
  const [addOpen, setAddOpen] = useState(false)
  const [addTitle, setAddTitle] = useState('')
  const [addSaving, setAddSaving] = useState(false)
  const [addError, setAddError] = useState<string | null>(null)

  // 현재 페이지가 이미 화면 목록에 등록됐는지 (id가 있으면 DB에 실제 등록된 것)
  const isCurrentPageRegistered = screensLoaded && screens.some(s => s.pageId === currentPageId && s.id !== null)

  const handleSelect = (pageId: string) => {
    onSelect(pageId)
  }

  const openAddForm = () => {
    setAddTitle('')
    setAddError(null)
    setAddOpen(true)
  }

  const closeAddForm = () => {
    setAddOpen(false)
    setAddError(null)
  }

  const handleAddScreen = async () => {
    const title = addTitle.trim()
    if (!title) { setAddError('화면 이름을 입력해주세요.'); return }
    if (!storage.saveScreenSpec) return
    setAddSaving(true)
    setAddError(null)
    try {
      // 현재 페이지의 pageId로 등록
      const saved = await storage.saveScreenSpec(currentPageId, { title, updatedBy: currentAuthor || null })
      onScreenAdded?.(saved)
      closeAddForm()
    } catch (e: unknown) {
      const apiMsg = e && typeof e === 'object' && 'userMessage' in e ? (e as { userMessage?: string }).userMessage : undefined
      setAddError(apiMsg ?? '저장에 실패했습니다')
    } finally {
      setAddSaving(false)
    }
  }

  const handleDeleteScreen = async (pageId: string) => {
    if (!storage.deleteScreenSpec) return
    try {
      await storage.deleteScreenSpec(pageId)
      onScreenDeleted?.(pageId)
    } catch { /* ignore */ }
  }

  const statusCounts = useMemo(() =>
    ALL_STATUSES.reduce<Record<SpecStatus, number>>((acc, s) => {
      acc[s] = screens.filter(sc => (sc.status ?? 'draft') === s).length
      return acc
    }, {} as Record<SpecStatus, number>),
    [screens]
  )

  const sortScreens = (list: ScreenSpec[]) => {
    const active = list.filter(s => s.status !== 'deprecated').sort((a, b) => (a.title || a.pageId).localeCompare(b.title || b.pageId, 'ko'))
    const deprecated = list.filter(s => s.status === 'deprecated').sort((a, b) => (a.title || a.pageId).localeCompare(b.title || b.pageId, 'ko'))
    return [...active, ...deprecated]
  }
  const filtered = sortScreens(filterStatus ? screens.filter(s => (s.status ?? 'draft') === filterStatus) : screens)

  return (
    <div
      data-sb-ui="true"
      style={{
        position: 'fixed', top: 0, right: DRAWER_W, bottom: 45,
        width: 280,
        background: DARK.bg2,
        borderLeft: `1px solid ${DARK.brd}`,
        boxShadow: '-8px 0 32px rgba(0,0,0,.35)',
        display: 'flex', flexDirection: 'column',
        zIndex: 9994, fontFamily: FONT_FAMILY,
        animation: 'sbSlideLeft .15s ease',
      }}
    >
      <style>{`@keyframes sbSlideLeft{from{opacity:0;transform:translateX(16px)}to{opacity:1;transform:translateX(0)}}`}</style>

      {/* 헤더 */}
      <div style={{
        display: 'flex', alignItems: 'center',
        padding: '14px 16px 12px', flexShrink: 0,
      }}>
        <span style={{ flex: 1, fontSize: 12, fontWeight: 700, color: 'rgba(255,255,255,.7)', fontFamily: FONT_FAMILY }}>
          화면 목록
          <span style={{ marginLeft: 6, fontSize: 10, color: 'rgba(255,255,255,.3)', fontWeight: 400 }}>
            {filterStatus ? `${filtered.length} / ${screens.length}` : screens.length}
          </span>
        </span>
        {storage.saveScreenSpec && (
          <button
            onClick={() => {
              if (!screensLoaded || isCurrentPageRegistered) return
              addOpen ? closeAddForm() : openAddForm()
            }}
            title={addOpen ? '취소' : !screensLoaded ? '로딩 중…' : isCurrentPageRegistered ? '이미 등록된 화면입니다' : '현재 화면 등록'}
            disabled={(!screensLoaded || isCurrentPageRegistered) && !addOpen}
            style={{
              width: 22, height: 22, borderRadius: 3, fontSize: 15, lineHeight: 1,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              background: addOpen ? `${SPEC_COLOR}22` : 'transparent',
              border: `1px solid ${addOpen ? SPEC_COLOR : 'rgba(255,255,255,.15)'}`,
              color: addOpen ? SPEC_COLOR : (!screensLoaded || isCurrentPageRegistered ? 'rgba(255,255,255,.2)' : 'rgba(255,255,255,.45)'),
              cursor: (!screensLoaded || isCurrentPageRegistered) && !addOpen ? 'default' : 'pointer',
              transition: 'all .15s', flexShrink: 0,
            }}
            onMouseEnter={e => { if (!addOpen && screensLoaded && !isCurrentPageRegistered) { e.currentTarget.style.borderColor = SPEC_COLOR; e.currentTarget.style.color = SPEC_COLOR } }}
            onMouseLeave={e => { if (!addOpen) { e.currentTarget.style.borderColor = 'rgba(255,255,255,.15)'; e.currentTarget.style.color = screensLoaded && !isCurrentPageRegistered ? 'rgba(255,255,255,.45)' : 'rgba(255,255,255,.2)' } }}
          >{addOpen ? '×' : '+'}</button>
        )}
      </div>

      {/* 화면 추가 폼 */}
      {addOpen && (
        <div style={{ padding: '0 14px 12px', display: 'flex', flexDirection: 'column', gap: 6, flexShrink: 0, borderBottom: `1px solid ${DARK.brd}` }}>
          {/* 화면 이름 */}
          <div>
            <div style={{ fontSize: 9, color: 'rgba(255,255,255,.35)', fontFamily: FONT_FAMILY, marginBottom: 3 }}>화면 이름 <span style={{ color: '#f87171' }}>*</span></div>
            <input
              autoFocus
              type="text"
              value={addTitle}
              onChange={e => setAddTitle(e.target.value)}
              placeholder="예: 대시보드, 주문 목록…"
              onKeyDown={e => {
                if (e.key === 'Escape') { e.nativeEvent.stopImmediatePropagation(); closeAddForm() }
                if (e.key === 'Enter') { e.preventDefault(); handleAddScreen() }
              }}
              style={INPUT_STYLE}
            />
          </div>
          {/* 식별자 (현재 페이지, 수정 불가) */}
          <div>
            <div style={{ fontSize: 9, color: 'rgba(255,255,255,.25)', fontFamily: FONT_FAMILY, marginBottom: 3 }}>
              식별자 <span style={{ color: 'rgba(255,255,255,.2)', fontWeight: 400 }}>(현재 페이지)</span>
            </div>
            <input
              type="text"
              value={currentPageId}
              disabled
              readOnly
              style={{
                ...INPUT_STYLE,
                color: 'rgba(255,255,255,.25)',
                background: 'rgba(255,255,255,.03)',
                cursor: 'default',
                userSelect: 'all',
              }}
            />
          </div>
          {addError && (
            <div style={{ fontSize: 10, color: '#f87171', fontFamily: FONT_FAMILY, background: 'rgba(239,68,68,.1)', borderRadius: 3, padding: '4px 8px' }}>
              ⚠ {addError}
            </div>
          )}
          <div style={{ display: 'flex', gap: 5, justifyContent: 'flex-end' }}>
            <button
              onClick={closeAddForm}
              style={{ padding: '3px 10px', borderRadius: 3, fontSize: 10, background: 'transparent', border: `1px solid ${DARK.brd}`, color: DARK.txS, cursor: 'pointer', fontFamily: FONT_FAMILY }}
            >취소</button>
            <button
              onClick={handleAddScreen}
              disabled={!addTitle.trim() || addSaving}
              style={{ padding: '3px 10px', borderRadius: 3, fontSize: 10, fontWeight: 600, background: SPEC_COLOR, border: 'none', color: '#fff', cursor: 'pointer', fontFamily: FONT_FAMILY, opacity: !addTitle.trim() || addSaving ? 0.5 : 1 }}
            >{addSaving ? '저장 중…' : '추가'}</button>
          </div>
        </div>
      )}

      {/* 상태 필터 탭 */}
      <div style={{
        display: 'flex',
        borderBottom: '1px solid rgba(255,255,255,.08)',
        flexShrink: 0,
      }}>
        {/* 전체 탭 */}
        {(() => {
          const isActive = filterStatus === null
          return (
            <button
              onClick={() => setFilterStatus(null)}
              style={{
                flex: 1,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                padding: '8px 0',
                background: 'transparent', border: 'none',
                borderBottom: `2px solid ${isActive ? 'rgba(255,255,255,.7)' : 'transparent'}`,
                cursor: 'pointer', fontFamily: FONT_FAMILY, transition: 'border-color .15s',
              }}
              onMouseEnter={e => { if (!isActive) e.currentTarget.style.borderBottomColor = 'rgba(255,255,255,.2)' }}
              onMouseLeave={e => { if (!isActive) e.currentTarget.style.borderBottomColor = 'transparent' }}
            >
              <span style={{ fontSize: 10, fontWeight: isActive ? 700 : 400, color: isActive ? 'rgba(255,255,255,.85)' : 'rgba(255,255,255,.4)' }}>
                전체
              </span>
            </button>
          )
        })()}
        {ALL_STATUSES.map(status => {
          const cfg = STATUS_CFG[status]
          const count = statusCounts[status]
          const isActive = filterStatus === status
          return (
            <button
              key={status}
              onClick={() => setFilterStatus(prev => prev === status ? null : status)}
              style={{
                flex: 1,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                padding: '8px 0',
                background: 'transparent',
                border: 'none',
                borderBottom: `2px solid ${isActive ? cfg.color : 'transparent'}`,
                cursor: 'pointer',
                opacity: count === 0 ? 0.3 : 1,
                fontFamily: FONT_FAMILY,
                transition: 'border-color .15s',
              }}
              onMouseEnter={e => { if (!isActive) e.currentTarget.style.borderBottomColor = `${cfg.color}55` }}
              onMouseLeave={e => { if (!isActive) e.currentTarget.style.borderBottomColor = 'transparent' }}
            >
              <span style={{
                fontSize: 10, fontWeight: isActive ? 700 : 400,
                color: isActive ? cfg.color : 'rgba(255,255,255,.4)',
              }}>
                {cfg.label}
              </span>
            </button>
          )
        })}
      </div>

      {/* 목록 */}
      <div className="sb-scroll" style={{ flex: 1, overflowY: 'auto' }}>
        {filtered.length === 0 && (
          <div style={{ padding: '20px 16px', color: 'rgba(255,255,255,.25)', fontSize: 12 }}>
            해당 상태의 화면이 없습니다.
          </div>
        )}
        {filtered.map(s => {
          const isCurrent = s.pageId === currentPageId
          const cfg = STATUS_CFG[s.status ?? 'draft'] ?? STATUS_CFG.draft
          const canDelete = !!storage.deleteScreenSpec && s.id !== null
          return (
            <ScreenListItem
              key={s.pageId}
              s={s}
              isCurrent={isCurrent}
              cfg={cfg}
              canDelete={canDelete}
              allAnnotations={allAnnotations}
              onSelect={() => handleSelect(s.pageId)}
              onDelete={() => handleDeleteScreen(s.pageId)}
            />
          )
        })}
      </div>

      {/* 변경 이력 섹션 */}
      <ChangelogSection storage={storage} currentAuthor={currentAuthor} />
    </div>
  )
}

// ── 화면 스펙 탭 ──────────────────────────────────────────────────────────────

function ScreenSpecTab({ pageId, storage, currentAuthor, onDeleteElement, refreshKey, onScreenSpecSaved, externalTitle, onSoftDeleteElement, onRestoreElement, onHoverElement, onElementSaved }: {
  pageId: string
  storage: StorageAdapter
  currentAuthor: string
  onDeleteElement?: (id: string) => void
  refreshKey?: number
  onScreenSpecSaved?: (spec: ScreenSpec) => void
  externalTitle?: string
  onSoftDeleteElement?: (id: string) => void
  onRestoreElement?: (id: string) => void
  onHoverElement?: (elementId: string | null) => void
  onElementSaved?: (spec: PageSpec) => void
}) {
  const [screen, setScreen] = useState<ScreenSpec | null>(null)
  const [elements, setElements] = useState<PageSpec[]>([])
  const [feedback, setFeedback] = useState<{ type: 'ok' | 'err'; msg: string } | null>(null)
  const [hoveredItemId, setHoveredItemId] = useState<string | null>(null)
  const [renamingId, setRenamingId] = useState<string | null>(null)
  const [renameValue, setRenameValue] = useState('')
  const [editingContentId, setEditingContentId] = useState<string | null>(null)
  const [editContent, setEditContent] = useState('')
  const [collapsedIds, setCollapsedIds] = useState<Set<string>>(new Set())
  const [softDeletedIds, setSoftDeletedIds] = useState<Set<string>>(new Set())
  const [editingTitle, setEditingTitle] = useState(false)
  const [editTitleValue, setEditTitleValue] = useState('')
  const [editingDesc, setEditingDesc] = useState(false)
  const [editDescValue, setEditDescValue] = useState('')
  const [editingAuthor, setEditingAuthor] = useState(false)
  const [editAuthorValue, setEditAuthorValue] = useState('')

  useEffect(() => {
    if (storage.loadScreenSpec) storage.loadScreenSpec(pageId).then(setScreen).catch(() => {})
    if (storage.loadPageSpecs) storage.loadPageSpecs(pageId).then(setElements).catch(() => {})
  }, [pageId, storage, refreshKey])

  const showFeedback = (type: 'ok' | 'err', msg: string) => {
    setFeedback({ type, msg })
    setTimeout(() => setFeedback(null), 2500)
  }

  const saveScreen = async (patch: { title?: string; description?: string; status?: SpecStatus; updatedBy?: string | null }) => {
    if (!storage.saveScreenSpec) return
    try {
      // 현재 screen 값을 baseline으로 보내고 patch가 override — 다른 필드 초기화 방지
      const saved = await storage.saveScreenSpec(pageId, {
        title: screen?.title,
        description: screen?.description,
        status: screen?.status ?? 'draft',
        updatedBy: currentAuthor || null,
        ...patch,
      })
      setScreen(saved)
      onScreenSpecSaved?.(saved)
      showFeedback('ok', '저장됨')
    } catch (e) { showFeedback('err', e instanceof Error ? e.message : '저장 실패') }
  }

  const saveElement = async (spec: PageSpec, patch: {
    elementLabel?: string; title?: string; content?: string
  }) => {
    if (!storage.savePageSpec) return
    const saved = await storage.savePageSpec(pageId, spec.elementId, { ...patch, updatedBy: currentAuthor || null })
    setElements(prev => prev.map(e => e.id === spec.id ? saved : e))
    onElementSaved?.(saved)
    // 화면 스펙 최종 수정일 갱신 (title/description/status 유지)
    if (storage.saveScreenSpec) {
      const updatedScreen = await storage.saveScreenSpec(pageId, {
        title: screen?.title,
        description: screen?.description,
        status: screen?.status ?? 'draft',
        updatedBy: currentAuthor || null,
      })
      setScreen(updatedScreen)
      onScreenSpecSaved?.(updatedScreen)
    }
  }

  const toggleCollapse = (id: string) => {
    setCollapsedIds(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id); else next.add(id)
      return next
    })
  }

  const softDeleteElement = (spec: PageSpec) => {
    setSoftDeletedIds(prev => new Set([...prev, spec.id]))
    if (editingContentId === spec.id) setEditingContentId(null)
    onSoftDeleteElement?.(spec.id)
  }

  const hardDeleteElement = async (spec: PageSpec) => {
    const name = spec.elementLabel ?? spec.elementId
    if (!window.confirm(`"${name}" 요소를 완전히 삭제합니다.\n삭제 후 복구할 수 없습니다. 계속하시겠습니까?`)) return
    try {
      await storage.deletePageSpec?.(spec.id)
      setElements(prev => prev.filter(e => e.id !== spec.id))
      setSoftDeletedIds(prev => { const next = new Set(prev); next.delete(spec.id); return next })
      onDeleteElement?.(spec.id)
    } catch (e) { showFeedback('err', e instanceof Error ? e.message : '삭제 실패') }
  }

  const restoreElement = (spec: PageSpec) => {
    setSoftDeletedIds(prev => { const next = new Set(prev); next.delete(spec.id); return next })
    onRestoreElement?.(spec.id)
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', padding: '16px 8px 8px 8px' }}>

      <div>

        {/* 화면 상태 버튼 행 */}
        <div style={{ display: 'flex', gap: 4, marginBottom: 8, paddingLeft: 4, paddingRight: 4 }}>
          {ALL_STATUSES.map(s => {
            const cfg = STATUS_CFG[s]
            const isActive = (screen?.status ?? 'draft') === s
            return (
              <button
                key={s}
                onClick={() => saveScreen({ status: s })}
                style={{
                  flex: 1, padding: '0', height: 26, borderRadius: 3, fontSize: 10, fontWeight: 700,
                  border: `1px solid ${isActive ? cfg.color : DARK.brd}`,
                  background: isActive ? `${cfg.color}22` : 'transparent',
                  color: isActive ? cfg.color : DARK.txL,
                  cursor: 'pointer', fontFamily: FONT_FAMILY, transition: 'all .15s',
                }}
                onMouseEnter={e => { if (!isActive) { e.currentTarget.style.borderColor = cfg.color; e.currentTarget.style.color = cfg.color } }}
                onMouseLeave={e => { if (!isActive) { e.currentTarget.style.borderColor = DARK.brd; e.currentTarget.style.color = DARK.txL } }}
              >{cfg.label}</button>
            )
          })}
        </div>

        {/* 구분선 */}
        <div style={{ borderTop: `1px solid ${DARK.brd}`, margin: '8px 4px' }} />

        {/* 화면 이름 + 최종 수정일시 */}
        <div style={{ marginBottom: 6, paddingLeft: 4, paddingRight: 4 }}>
          {editingTitle ? (
            <input
              autoFocus
              value={editTitleValue}
              onChange={e => setEditTitleValue(e.target.value)}
              onBlur={() => { const t = editTitleValue.trim(); if (t) saveScreen({ title: t }); setEditingTitle(false) }}
              onKeyDown={e => {
                if (e.key === 'Escape') { e.nativeEvent.stopImmediatePropagation(); setEditingTitle(false) }
                if (e.key === 'Enter') { e.preventDefault(); const t = editTitleValue.trim(); if (t) saveScreen({ title: t }); setEditingTitle(false) }
              }}
              style={{
                width: '100%', boxSizing: 'border-box',
                background: DARK.bg3, border: `1px solid ${SPEC_COLOR}66`,
                borderRadius: 3, padding: '4px 8px',
                color: DARK.txt, fontSize: 18, fontWeight: 700, fontFamily: FONT_FAMILY,
                outline: 'none',
              }}
            />
          ) : (
            <div style={{ display: 'flex', alignItems: 'center' }}>
              <span
                onDoubleClick={() => { setEditingTitle(true); setEditTitleValue(externalTitle ?? screen?.title ?? pageId) }}
                title="더블클릭하여 수정"
                style={{ fontSize: 18, fontWeight: 700, color: DARK.txt, flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', cursor: 'text' }}
              >
                {externalTitle ?? screen?.title ?? pageId}
              </span>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexShrink: 0, marginLeft: 8 }}>
                {screen?.updatedAt && (
                  <span style={{ fontSize: 10, color: DARK.txL, fontFamily: FONT_FAMILY }}>
                    {fmtDate(screen.updatedAt)}
                  </span>
                )}
                {editingAuthor ? (
                  <input
                    autoFocus
                    value={editAuthorValue}
                    onChange={e => setEditAuthorValue(e.target.value)}
                    onKeyDown={e => {
                      if (e.key === 'Escape') { e.nativeEvent.stopImmediatePropagation(); setEditingAuthor(false) }
                      if (e.key === 'Enter') {
                        e.preventDefault()
                        const v = editAuthorValue.trim()
                        if (v) saveScreen({ updatedBy: v })
                        setEditingAuthor(false)
                      }
                    }}
                    onBlur={() => {
                      const v = editAuthorValue.trim()
                      if (v) saveScreen({ updatedBy: v })
                      setEditingAuthor(false)
                    }}
                    style={{
                      fontSize: 10, width: 80, padding: '1px 5px', borderRadius: 3,
                      background: 'rgba(255,255,255,.08)', border: `1px solid ${SPEC_COLOR}66`,
                      color: 'rgba(255,255,255,.8)', fontFamily: FONT_FAMILY, outline: 'none',
                    }}
                  />
                ) : (
                  <span
                    onDoubleClick={() => { setEditAuthorValue(screen?.updatedBy || screen?.createdBy || ''); setEditingAuthor(true) }}
                    title="더블클릭하여 작성자 변경"
                    style={{
                      fontSize: 10, color: SPEC_COLOR, fontFamily: FONT_FAMILY,
                      cursor: 'text',
                    }}
                  >
                    {screen?.updatedBy || screen?.createdBy || '작성자'}
                  </span>
                )}
              </div>
            </div>
          )}
        </div>

        {/* 화면 설명 */}
        <div style={{ marginBottom: 6, paddingLeft: 4, paddingRight: 4 }}>
          {editingDesc ? (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
              <textarea
                autoFocus
                value={editDescValue}
                onChange={e => {
                  setEditDescValue(e.target.value)
                  e.target.style.height = 'auto'
                  e.target.style.height = e.target.scrollHeight + 'px'
                }}
                ref={el => { if (el) { el.style.height = 'auto'; el.style.height = el.scrollHeight + 'px' } }}
                onKeyDown={e => {
                  if (e.key === 'Escape') { e.nativeEvent.stopImmediatePropagation(); setEditingDesc(false) }
                  if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
                    e.preventDefault()
                    saveScreen({ description: editDescValue.trim() })
                    setEditingDesc(false)
                  }
                }}
                placeholder="화면 전반에 대한 설명…"
                style={{
                  width: '100%', boxSizing: 'border-box', resize: 'none', overflow: 'hidden',
                  background: DARK.bg3, border: `1px solid ${SPEC_COLOR}66`,
                  borderRadius: 3, padding: '5px 8px',
                  color: DARK.txt, fontSize: 11, fontFamily: FONT_FAMILY,
                  outline: 'none', lineHeight: 1.6, minHeight: 56,
                }}
              />
              <div style={{ display: 'flex', gap: 5, justifyContent: 'flex-end' }}>
                <button
                  onClick={() => setEditingDesc(false)}
                  style={{ padding: '3px 10px', borderRadius: 3, fontSize: 10, background: 'transparent', border: `1px solid ${DARK.brd}`, color: DARK.txS, cursor: 'pointer', fontFamily: FONT_FAMILY }}
                >취소</button>
                <button
                  onClick={() => { saveScreen({ description: editDescValue.trim() }); setEditingDesc(false) }}
                  style={{ padding: '3px 10px', borderRadius: 3, fontSize: 10, fontWeight: 600, background: SPEC_COLOR, border: 'none', color: '#fff', cursor: 'pointer', fontFamily: FONT_FAMILY }}
                >저장</button>
              </div>
            </div>
          ) : (
            <div
              onDoubleClick={() => { setEditingDesc(true); setEditDescValue(screen?.description ?? '') }}
              title="더블클릭하여 수정"
              style={{
                fontSize: 11, color: screen?.description ? DARK.txS : DARK.txL,
                lineHeight: 1.6, cursor: 'text', fontFamily: FONT_FAMILY,
                minHeight: 36, whiteSpace: 'pre-wrap',
              }}
            >
              {screen?.description || '더블 클릭 하면 내용을 입력하실 수 있습니다.'}
            </div>
          )}

        </div>

        {/* 구분선 */}
        <div style={{ borderTop: 'none', borderBottom: `3px solid ${DARK.brd}`, margin: '8px 4px' }} />

        {/* 요소 스펙 헤더 */}
        <div style={{ padding: '4px 4px 6px', display: 'flex', alignItems: 'center' }}>
          <span style={{ flex: 1, fontSize: 10, color: DARK.txL, fontFamily: FONT_FAMILY, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.4px' }}>
            요소 스펙 {elements.length > 0 && <span style={{ fontWeight: 400 }}>({elements.length})</span>}
          </span>
          {elements.length > 0 && (
            <div style={{ display: 'flex', gap: 2 }}>
              <button
                onClick={() => setCollapsedIds(new Set(elements.map(e => e.id)))}
                style={{ border: `1px solid ${DARK.brd}`, background: 'transparent', color: DARK.txL, cursor: 'pointer', fontSize: 10, fontFamily: FONT_FAMILY, padding: '2px 6px', borderRadius: 3 }}
                onMouseEnter={e => { e.currentTarget.style.color = SPEC_COLOR; e.currentTarget.style.borderColor = SPEC_COLOR }}
                onMouseLeave={e => { e.currentTarget.style.color = DARK.txL; e.currentTarget.style.borderColor = DARK.brd }}
              >접기</button>
              <button
                onClick={() => setCollapsedIds(new Set())}
                style={{ border: `1px solid ${DARK.brd}`, background: 'transparent', color: DARK.txL, cursor: 'pointer', fontSize: 10, fontFamily: FONT_FAMILY, padding: '2px 6px', borderRadius: 3 }}
                onMouseEnter={e => { e.currentTarget.style.color = SPEC_COLOR; e.currentTarget.style.borderColor = SPEC_COLOR }}
                onMouseLeave={e => { e.currentTarget.style.color = DARK.txL; e.currentTarget.style.borderColor = DARK.brd }}
              >펼치기</button>
            </div>
          )}
        </div>

      </div>

      {/* ── 요소 목록 스크롤 영역 ── */}
      <div className="sb-scroll" style={{ flex: 1, overflowY: 'auto' }}>

        {/* 요소 없음 */}
        {elements.length === 0 && (
          <div style={{
            textAlign: 'center', color: DARK.txL, fontSize: 11,
            marginTop: 24, lineHeight: 1.8, fontFamily: FONT_FAMILY,
          }}>
            "+ 추가"를 눌러<br />화면 요소를 선택하세요
          </div>
        )}

        {/* 요소 목록 — 플랫 리스트 (num 오름차순) */}
        {[...elements].sort((a, b) => (a.num ?? Infinity) - (b.num ?? Infinity)).map((spec, idx) => (
          <div
            key={spec.id}
            onMouseEnter={() => { setHoveredItemId(spec.id); onHoverElement?.(spec.elementId) }}
            onMouseLeave={() => { setHoveredItemId(null); onHoverElement?.(null) }}
            style={{
              padding: '10px 4px',
              borderBottom: idx < elements.length - 1 ? `1px solid ${DARK.brd}` : 'none',
              background: softDeletedIds.has(spec.id)
                ? 'rgba(239,68,68,.06)'
                : hoveredItemId === spec.id
                ? 'rgba(59,130,246,.08)'
                : 'transparent',
              cursor: 'pointer',
              transition: 'background .15s',
            }}
          >
            {/* 헤더: 배지(접기/펼침) + 제목 + 시간 + 삭제 */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: collapsedIds.has(spec.id) ? 0 : 4 }}>
              {/* 배지 — 클릭하면 접기/펼치기만 */}
              <div
                onClick={e => { e.stopPropagation(); if (renamingId !== spec.id) toggleCollapse(spec.id) }}
                style={{
                  width: 18, height: 18,
                  borderRadius: collapsedIds.has(spec.id) ? '50% 50% 0 50%' : '50%',
                  background: BADGE_COLOR, color: '#fff',
                  fontSize: 9, fontWeight: 800, flexShrink: 0,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontFamily: FONT_FAMILY,
                  transition: 'border-radius .2s',
                  cursor: 'pointer',
                }}>
                {spec.num ?? '·'}
              </div>

              {/* 제목 — 더블클릭 편집, 단순 클릭은 카드 선택으로 버블링 */}
              <div style={{ flex: 1, minWidth: 0 }}>
                {renamingId === spec.id ? (
                  <input
                    autoFocus
                    value={renameValue}
                    onClick={e => e.stopPropagation()}
                    onChange={e => setRenameValue(e.target.value)}
                    onKeyDown={e => {
                      e.stopPropagation()
                      if (e.key === 'Enter') {
                        const t = renameValue.trim()
                        if (t) saveElement(spec, { elementLabel: t })
                        setRenamingId(null)
                      }
                      if (e.key === 'Escape') { e.nativeEvent.stopImmediatePropagation(); setRenamingId(null) }
                    }}
                    onBlur={() => {
                      const t = renameValue.trim()
                      if (t && t !== (spec.elementLabel ?? spec.elementId)) saveElement(spec, { elementLabel: t })
                      setRenamingId(null)
                    }}
                    style={{
                      width: '100%', fontSize: 12, fontWeight: 600,
                      background: DARK.bg3, border: `1px solid ${SPEC_COLOR}66`,
                      borderRadius: 3, padding: '1px 6px',
                      color: DARK.txt, fontFamily: FONT_FAMILY,
                      outline: 'none', boxSizing: 'border-box',
                    }}
                  />
                ) : (
                  <span
                    onDoubleClick={e => { e.stopPropagation(); setRenamingId(spec.id); setRenameValue(spec.elementLabel ?? spec.elementId) }}
                    title="더블클릭하여 이름 수정"
                    style={{
                      fontSize: 12, fontWeight: 600,
                      color: softDeletedIds.has(spec.id) ? DARK.txL : DARK.txt,
                      overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                      fontFamily: FONT_FAMILY, display: 'block',
                      textDecoration: softDeletedIds.has(spec.id) ? 'line-through' : 'none',
                    }}
                  >
                    {spec.elementLabel ?? spec.elementId}
                  </span>
                )}
              </div>

              {spec.updatedAt && (
                <span style={{
                  fontSize: 9, color: DARK.txL, fontFamily: FONT_FAMILY,
                  flexShrink: 0, whiteSpace: 'nowrap',
                }}>
                  {fmtDate(spec.updatedAt)}
                </span>
              )}

              {softDeletedIds.has(spec.id) ? (
                <div style={{ display: 'flex', gap: 4, flexShrink: 0 }}>
                  <button
                    onClick={e => { e.stopPropagation(); hardDeleteElement(spec) }}
                    style={{ fontSize: 10, fontFamily: FONT_FAMILY, padding: '2px 6px', borderRadius: 3, cursor: 'pointer', border: '1px solid rgba(239,68,68,.4)', background: 'transparent', color: '#f87171' }}
                    onMouseEnter={e => { e.currentTarget.style.background = 'rgba(239,68,68,.18)' }}
                    onMouseLeave={e => { e.currentTarget.style.background = 'transparent' }}
                  >삭제</button>
                  <button
                    onClick={e => { e.stopPropagation(); restoreElement(spec) }}
                    style={{ fontSize: 10, fontFamily: FONT_FAMILY, padding: '2px 6px', borderRadius: 3, cursor: 'pointer', border: `1px solid ${SPEC_COLOR}66`, background: 'transparent', color: SPEC_COLOR }}
                    onMouseEnter={e => { e.currentTarget.style.background = `${SPEC_COLOR}18` }}
                    onMouseLeave={e => { e.currentTarget.style.background = 'transparent' }}
                  >복원</button>
                </div>
              ) : (
                <button
                  onClick={e => { e.stopPropagation(); softDeleteElement(spec) }}
                  title="요소 삭제"
                  style={{
                    flexShrink: 0, width: 18, height: 18,
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    borderRadius: 3, border: '1px solid transparent',
                    background: 'transparent', color: DARK.txL,
                    fontSize: 11, fontWeight: 700, lineHeight: 1,
                    cursor: 'pointer', fontFamily: FONT_FAMILY, padding: 0,
                    opacity: hoveredItemId === spec.id ? 1 : 0.35,
                    transition: 'opacity .15s, background .15s, border-color .15s, color .15s',
                  }}
                  onMouseEnter={e => {
                    e.currentTarget.style.background = 'rgba(239,68,68,.18)'
                    e.currentTarget.style.borderColor = 'rgba(239,68,68,.4)'
                    e.currentTarget.style.color = '#f87171'
                  }}
                  onMouseLeave={e => {
                    e.currentTarget.style.background = 'transparent'
                    e.currentTarget.style.borderColor = 'transparent'
                    e.currentTarget.style.color = DARK.txL
                  }}
                >×</button>
              )}
            </div>

            {/* 내용 — 더블클릭하면 textarea 편집 */}
            {!collapsedIds.has(spec.id) && <div style={{ paddingLeft: 24 }}>
              {editingContentId === spec.id ? (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                  <textarea
                    autoFocus
                    value={editContent}
                    onChange={e => {
                      setEditContent(e.target.value)
                      e.target.style.height = 'auto'
                      e.target.style.height = e.target.scrollHeight + 'px'
                    }}
                    ref={el => { if (el) { el.style.height = 'auto'; el.style.height = el.scrollHeight + 'px' } }}
                    onKeyDown={e => {
                      if (e.key === 'Escape') { e.nativeEvent.stopImmediatePropagation(); setEditingContentId(null) }
                      if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
                        e.preventDefault()
                        saveElement(spec, { content: editContent })
                        setEditingContentId(null)
                      }
                    }}
                    placeholder="스펙 내용…"
                    style={{
                      width: '100%', boxSizing: 'border-box', resize: 'none', overflow: 'hidden',
                      background: DARK.bg3, border: `1px solid ${SPEC_COLOR}66`,
                      borderRadius: 3, padding: '5px 8px',
                      color: DARK.txt, fontSize: 11, fontFamily: FONT_FAMILY,
                      outline: 'none', lineHeight: 1.6, minHeight: 36,
                    }}
                  />
                  <div style={{ display: 'flex', gap: 5, justifyContent: 'flex-end' }}>
                    <button
                      onClick={() => setEditingContentId(null)}
                      style={{
                        padding: '3px 10px', borderRadius: 3, fontSize: 10,
                        background: 'transparent', border: `1px solid ${DARK.brd}`,
                        color: DARK.txS, cursor: 'pointer', fontFamily: FONT_FAMILY,
                      }}
                    >취소</button>
                    <button
                      onClick={() => { saveElement(spec, { content: editContent }); setEditingContentId(null) }}
                      style={{
                        padding: '3px 10px', borderRadius: 3, fontSize: 10, fontWeight: 600,
                        background: SPEC_COLOR, border: 'none',
                        color: '#fff', cursor: 'pointer', fontFamily: FONT_FAMILY,
                      }}
                    >저장</button>
                  </div>
                </div>
              ) : (
                <div
                  onDoubleClick={() => { setEditingContentId(spec.id); setEditContent(spec.content ?? '') }}
                  title="더블클릭하여 내용 수정"
                  style={{
                    fontSize: 11, color: spec.content ? DARK.txS : DARK.txL,
                    lineHeight: 1.6, cursor: 'text', fontFamily: FONT_FAMILY,
                    minHeight: 20, whiteSpace: 'pre-wrap',
                    textDecoration: softDeletedIds.has(spec.id) ? 'line-through' : 'none',
                  }}
                >
                  {spec.content || '더블 클릭 하면 내용을 입력하실 수 있습니다.'}
                </div>
              )}
            </div>}
          </div>
        ))}
      </div>

      {/* 피드백 토스트 */}
      {feedback && (
        <div style={{
          padding: '5px 16px', fontSize: 10, fontFamily: FONT_FAMILY,
          color: feedback.type === 'ok' ? '#4ade80' : '#f87171',
          background: feedback.type === 'ok' ? 'rgba(34,197,94,.08)' : 'rgba(239,68,68,.08)',
          borderTop: `1px solid ${DARK.brd}`, flexShrink: 0,
        }}>
          {feedback.type === 'ok' ? '✓ ' : '⚠ '}{feedback.msg}
        </div>
      )}
    </div>
  )
}


// ── Comment 탭 (기존 AnnotList 통합) ──────────────────────────────────────────

function CommentTab({ pins, labels, screenTitle, screenUpdatedAt, screenDescription, selectedId, hoveredId, showResolved, resolvedCount, onSelect, onHover, onToggleShowResolved, sessions, currentSessionId, sessionProgress, onSelectSession, onCreateSession, onDeleteSession, onSetSessionStatus, onUpdateSession }: {
  pins: Pin[]
  labels: LabelDef[]
  screenTitle?: string
  screenUpdatedAt?: string | null
  screenDescription?: string
  selectedId: string | null
  hoveredId?: string | null
  showResolved: boolean
  resolvedCount: number
  onSelect: (id: string) => void
  onHover?: (id: string | null) => void
  onToggleShowResolved: () => void
  sessions?: AnnotSession[]
  currentSessionId?: string | null
  sessionProgress?: Record<string, { total: number; resolved: number }>
  onSelectSession?: (id: string | null) => void
  onCreateSession?: (name: string, options?: { viewport?: SessionViewport | null }) => Promise<string | null>
  onDeleteSession?: (id: string) => Promise<void>
  onSetSessionStatus?: (id: string, status: SessionStatus) => Promise<void | AnnotSession>
  onUpdateSession?: (id: string, patch: Partial<Pick<AnnotSession, 'name' | 'status' | 'viewport' | 'note'>>) => Promise<void | AnnotSession>
}) {
  const labelById = new Map(labels.map(l => [l.id, l]))
  const [authorFilter, setAuthorFilter] = useState<string | null>(null)
  const [labelFilterIds, setLabelFilterIds] = useState<Set<string>>(new Set())
  const uniqueAuthors = Array.from(new Set(pins.map(p => p.author).filter((a): a is string => !!a)))
  const resolvedTotal = pins.filter(p => p.status === 'resolved').length
  const basePins = showResolved ? pins : pins.filter(p => p.status !== 'resolved')
  const labelFiltered = labelFilterIds.size === 0 ? basePins : basePins.filter(p => p.labelId && labelFilterIds.has(p.labelId))
  const filtered = authorFilter ? labelFiltered.filter(p => p.author === authorFilter) : labelFiltered
  const currentSession = sessions?.find(s => s.id === currentSessionId) ?? null
  const [editingNote, setEditingNote] = useState(false)
  const [noteValue, setNoteValue] = useState('')

  const [labelDropOpen, setLabelDropOpen] = useState(false)
  const labelDropRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!labelDropOpen) return
    const h = (e: MouseEvent) => {
      if (labelDropRef.current && !labelDropRef.current.contains(e.target as Node)) setLabelDropOpen(false)
    }
    document.addEventListener('mousedown', h)
    return () => document.removeEventListener('mousedown', h)
  }, [labelDropOpen])

  const toggleLabelFilter = (id: string) => {
    setLabelFilterIds(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const labelTriggerText = labelFilterIds.size === 0
    ? '전체'
    : Array.from(labelFilterIds).map(id => labelById.get(id)?.name ?? id).join(', ')

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', padding: '16px 8px 8px' }}>

      {/* ── 상단 컨트롤 1행: 레이블필터 + 작성자 + 검토회차 ── */}
      <div style={{
        display: 'flex', gap: 4, alignItems: 'center',
        paddingLeft: 4, paddingRight: 4,
      }}>
        {/* 검토회차 */}
        {sessions && sessions.length > 0 && onSelectSession && onCreateSession && onDeleteSession && (
          <div style={{ flex: 1, minWidth: 0 }}>
            <SessionPicker
              sessions={sessions}
              currentSessionId={currentSessionId ?? null}
              sessionProgress={sessionProgress}
              onSelectSession={onSelectSession}
              onCreateSession={onCreateSession}
              onDeleteSession={onDeleteSession}
              onSetSessionStatus={onSetSessionStatus}
              onUpdateSession={onUpdateSession}
              placement="bottom"
            />
          </div>
        )}
        {/* 레이블 멀티셀렉트 드롭다운 */}
        {labels.length > 0 && (
          <div ref={labelDropRef} style={{ position: 'relative', flex: 1, minWidth: 0 }}>
            <button
              onClick={() => setLabelDropOpen(v => !v)}
              style={{
                display: 'flex', alignItems: 'center', gap: 3,
                padding: '5px 8px', borderRadius: 2, cursor: 'pointer',
                border: `1px solid ${labelFilterIds.size > 0 ? 'rgba(59,130,246,.4)' : 'rgba(255,255,255,.07)'}`,
                background: labelDropOpen ? 'rgba(255,255,255,.07)' : 'transparent',
                color: labelFilterIds.size > 0 ? 'rgba(59,130,246,.9)' : 'rgba(255,255,255,.7)',
                fontSize: 11, fontWeight: 500, outline: 'none', fontFamily: FONT_FAMILY,
                height: 26, width: '100%', whiteSpace: 'nowrap', overflow: 'hidden',
                transition: 'all .15s',
              }}
              onMouseEnter={e => {
                e.currentTarget.style.background = 'rgba(255,255,255,.07)'
                e.currentTarget.style.color = labelFilterIds.size > 0 ? 'rgba(59,130,246,1)' : 'rgba(255,255,255,1)'
                e.currentTarget.style.borderColor = labelFilterIds.size > 0 ? 'rgba(59,130,246,.6)' : 'rgba(255,255,255,.15)'
              }}
              onMouseLeave={e => {
                e.currentTarget.style.background = labelDropOpen ? 'rgba(255,255,255,.07)' : 'transparent'
                e.currentTarget.style.color = labelFilterIds.size > 0 ? 'rgba(59,130,246,.9)' : 'rgba(255,255,255,.7)'
                e.currentTarget.style.borderColor = labelFilterIds.size > 0 ? 'rgba(59,130,246,.4)' : 'rgba(255,255,255,.07)'
              }}
            >
              <span style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', textAlign: 'left' }}>{labelTriggerText}</span>
              <span style={{ fontSize: 8, opacity: 0.6, marginLeft: 1 }}>▾</span>
            </button>
            {labelDropOpen && (
              <div style={{
                position: 'absolute', top: 'calc(100% + 4px)', left: 0, zIndex: 200,
                background: DARK.bg2, border: `1px solid ${DARK.brd}`,
                borderRadius: 4, overflow: 'hidden', minWidth: 120,
                boxShadow: '0 8px 24px rgba(0,0,0,.5)',
              }}>
                {/* 전체 초기화 */}
                <div
                  onClick={() => setLabelFilterIds(new Set())}
                  style={{
                    display: 'flex', alignItems: 'center', gap: 8,
                    padding: '6px 10px', cursor: 'pointer',
                    background: labelFilterIds.size === 0 ? 'rgba(255,255,255,.06)' : 'transparent',
                    borderBottom: `1px solid ${DARK.brd}`,
                  }}
                >
                  <span style={{
                    width: 12, fontSize: 9, textAlign: 'center', flexShrink: 0,
                    color: labelFilterIds.size === 0 ? 'rgba(255,255,255,.7)' : 'transparent',
                  }}>✓</span>
                  <span style={{
                    fontSize: 11, fontFamily: FONT_FAMILY,
                    color: labelFilterIds.size === 0 ? DARK.txt : DARK.txL,
                    fontWeight: labelFilterIds.size === 0 ? 600 : 400,
                  }}>전체</span>
                </div>
                {/* 레이블 항목들 */}
                {labels.map(l => {
                  const active = labelFilterIds.has(l.id)
                  const color = l.color || FALLBACK_LABEL_COLOR
                  return (
                    <div
                      key={l.id}
                      onClick={() => toggleLabelFilter(l.id)}
                      style={{
                        display: 'flex', alignItems: 'center', gap: 8,
                        padding: '6px 10px', cursor: 'pointer',
                        background: active ? `${color}14` : 'transparent',
                        transition: 'background .1s',
                      }}
                      onMouseEnter={e => { if (!active) (e.currentTarget as HTMLElement).style.background = 'rgba(255,255,255,.04)' }}
                      onMouseLeave={e => { if (!active) (e.currentTarget as HTMLElement).style.background = 'transparent' }}
                    >
                      <span style={{
                        width: 12, fontSize: 9, textAlign: 'center', flexShrink: 0,
                        color: active ? color : 'transparent',
                      }}>✓</span>
                      <span style={{ width: 6, height: 6, borderRadius: '50%', background: color, flexShrink: 0 }} />
                      <span style={{
                        fontSize: 11, fontFamily: FONT_FAMILY,
                        color: active ? color : DARK.txL,
                        fontWeight: active ? 600 : 400,
                      }}>{l.name}</span>
                    </div>
                  )
                })}
              </div>
            )}
          </div>
        )}
        {/* 작성자 */}
        <select
          value={authorFilter ?? ''}
          onChange={e => setAuthorFilter(e.target.value || null)}
          disabled={uniqueAuthors.length === 0}
          style={{
            flex: 1, minWidth: 0,
            padding: '5px 8px', background: DARK.bg3,
            border: `1px solid ${authorFilter ? 'rgba(59,130,246,.4)' : 'rgba(255,255,255,.07)'}`,
            borderRadius: 2, color: authorFilter ? 'rgba(59,130,246,.9)' : 'rgba(255,255,255,.7)',
            fontSize: 11, fontWeight: 500,
            cursor: uniqueAuthors.length > 0 ? 'pointer' : 'default',
            outline: 'none', fontFamily: FONT_FAMILY,
            height: 26, transition: 'all .15s',
            opacity: uniqueAuthors.length === 0 ? 0.4 : 1,
          }}
        >
          <option value="">작성자</option>
          {uniqueAuthors.map(a => <option key={a} value={a}>{a}</option>)}
        </select>
      </div>
      <div style={{ borderTop: `1px solid ${DARK.brd}`, margin: '8px 4px' }} />

      {/* ── 화면 타이틀 ── */}
      {screenTitle && (
        <>
          <div style={{ marginBottom: 6, paddingLeft: 4, paddingRight: 4 }}>
            <div style={{ display: 'flex', alignItems: 'center' }}>
              <span title="화면 명칭" style={{
                fontSize: 18, fontWeight: 700, color: 'rgba(255,255,255,.88)',
                flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                fontFamily: FONT_FAMILY,
              }}>{screenTitle}</span>
              {screenUpdatedAt && (
                <span style={{ fontSize: 10, color: 'rgba(255,255,255,.3)', flexShrink: 0, marginLeft: 8, fontFamily: FONT_FAMILY }}>
                  {fmtDate(screenUpdatedAt)}
                </span>
              )}
            </div>
          </div>
          <div style={{ paddingLeft: 4, paddingRight: 4 }}>
            <div style={{
              fontSize: 11, color: screenDescription ? 'rgba(255,255,255,.55)' : 'rgba(255,255,255,.3)',
              lineHeight: 1.6, fontFamily: FONT_FAMILY, minHeight: 36, whiteSpace: 'pre-wrap',
            }}>
              {screenDescription || '더블 클릭 하면 내용을 입력하실 수 있습니다.'}
            </div>
          </div>
        </>
      )}

      <div style={{ borderBottom: `3px solid ${DARK.brd}`, margin: '8px 4px' }} />

      {/* ── 핀 목록 타이틀 ── */}
      <div style={{ padding: '4px 4px 6px', display: 'flex', alignItems: 'center', flexShrink: 0 }}>
        <span style={{ flex: 1, fontSize: 10, color: DARK.txL, fontFamily: FONT_FAMILY, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.4px' }}>
          코멘트 {filtered.length > 0 && <span style={{ fontWeight: 400 }}>({filtered.length})</span>}
        </span>
        {resolvedTotal > 0 && (
          <button onClick={onToggleShowResolved} style={{
            display: 'flex', alignItems: 'center', gap: 3,
            padding: '3px 8px', borderRadius: 3, cursor: 'pointer',
            border: `1px solid ${showResolved ? 'rgba(22,163,74,.5)' : DARK.brd}`,
            background: showResolved ? 'rgba(22,163,74,.15)' : 'transparent',
            color: showResolved ? '#4ade80' : DARK.txL,
            fontSize: 10, fontWeight: 600, fontFamily: FONT_FAMILY,
          }}>
            <span>{showResolved ? '✓' : '○'}</span>
            <span>해결 {resolvedTotal}</span>
          </button>
        )}
      </div>

      {/* ── 핀 목록 ── */}
      <div className="sb-scroll" style={{ flex: 1, overflowY: 'auto' }}>
        {filtered.length === 0 ? (
          <div style={{ textAlign: 'center', color: DARK.txL, fontSize: 11, marginTop: 36, lineHeight: 1.8, fontFamily: FONT_FAMILY }}>
            {authorFilter || labelFilterIds.size > 0 ? '필터 조건에 맞는 코멘트가 없습니다.' : '아직 추가된 코멘트가 없습니다.'}
          </div>
        ) : filtered.map((p, idx) => {
          const sel = p.id === selectedId
          const hov = p.id === hoveredId
          const label = p.labelId ? labelById.get(p.labelId) : undefined
          const color = label?.color ?? FALLBACK_LABEL_COLOR
          const resolved = p.status === 'resolved'
          return (
            <div
              key={p.id}
              onClick={() => onSelect(p.id)}
              onMouseEnter={() => onHover?.(p.id)}
              onMouseLeave={() => onHover?.(null)}
              style={{
                padding: '10px 4px',
                borderBottom: idx < filtered.length - 1 ? `1px solid ${DARK.brd}` : 'none',
                cursor: 'pointer',
                background: sel ? `${color}1a` : hov ? 'rgba(59,130,246,.12)' : 'transparent',
                transition: 'background .15s',
                opacity: resolved ? 0.65 : 1,
              }}
            >
              {/* 번호 + 작성자 | 공백 | 작성일 */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <div style={{
                  position: 'relative', width: 18, height: 18, borderRadius: '50%',
                  background: color, color: '#fff', fontSize: 9, fontWeight: 700, flexShrink: 0,
                  display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: FONT_FAMILY,
                }}>
                  {p.num}
                  {resolved && (
                    <span style={{
                      position: 'absolute', top: -3, right: -3,
                      width: 10, height: 10, borderRadius: '50%',
                      background: '#16a34a', color: '#fff', fontSize: 6, fontWeight: 900,
                      display: 'flex', alignItems: 'center', justifyContent: 'center',
                      border: '1.5px solid #1e1e1e',
                    }}>✓</span>
                  )}
                </div>
                <span style={{
                  fontSize: 12, fontWeight: 600,
                  color: resolved ? DARK.txL : DARK.txt,
                  fontFamily: FONT_FAMILY,
                  overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                  textDecoration: resolved ? 'line-through' : 'none',
                }}>{p.author || '익명'}</span>
                <div style={{ flex: 1 }} />
                {p.comments.length > 0 && (
                  <span style={{ fontSize: 9, padding: '1px 6px', background: 'rgba(59,130,246,.2)', color: '#93C5FD', borderRadius: 4, fontWeight: 700, fontFamily: FONT_FAMILY, flexShrink: 0, display: 'inline-flex', alignItems: 'center', gap: 3 }}><IconChat size={9} color="#93C5FD"/> {p.comments.length}</span>
                )}
                <span style={{ fontSize: 9, color: DARK.txL, fontFamily: FONT_FAMILY, flexShrink: 0 }}>{fmtDate(p.createdAt)}</span>
              </div>

              {/* 노트 */}
              {p.note && (
                <div style={{ paddingLeft: 24, marginTop: 4, marginBottom: 2 }}>
                  <div style={{ fontSize: 11, color: DARK.txL, fontFamily: FONT_FAMILY, lineHeight: 1.55, whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>{p.note}</div>
                </div>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

// ── SpecDrawer ────────────────────────────────────────────────────────────────

type DrawerTab = 'screenSpec' | 'comment'

const TABS: { key: DrawerTab; label: string }[] = [
  { key: 'screenSpec', label: '화면 스펙' },
  { key: 'comment',    label: '코멘트' },
]

interface Props {
  pageId: string
  storage: StorageAdapter
  currentAuthor: string
  onClose: () => void
  onDeleteElement?: (id: string) => void
  onSoftDeleteElement?: (id: string) => void
  onRestoreElement?: (id: string) => void
  onScreenSpecSaved?: (spec: ScreenSpec) => void
  onElementSaved?: (spec: PageSpec) => void
  refreshKey?: number
  // Comment 탭 (AnnotList 통합)
  pins?: Pin[]
  labels?: LabelDef[]
  selectedPinId?: string | null
  hoveredPinId?: string | null
  showResolved?: boolean
  resolvedCount?: number
  onSelectPin?: (id: string) => void
  onHoverPin?: (id: string | null) => void
  onToggleShowResolved?: () => void
  defaultTab?: DrawerTab
  // 검토 회차 (코멘트 탭에서 관리)
  sessions?: AnnotSession[]
  currentSessionId?: string | null
  sessionProgress?: Record<string, { total: number; resolved: number }>
  onSelectSession?: (id: string | null) => void
  onCreateSession?: (name: string, options?: { viewport?: SessionViewport | null }) => Promise<string | null>
  onDeleteSession?: (id: string) => Promise<void>
  onSetSessionStatus?: (id: string, status: SessionStatus) => Promise<void | AnnotSession>
  onUpdateSession?: (id: string, patch: Partial<Pick<AnnotSession, 'name' | 'status' | 'viewport' | 'note'>>) => Promise<void | AnnotSession>
  onHoverElement?: (elementId: string | null) => void
  allAnnotations?: import('./types').PagePins
  onNavigate?: (pageId: string) => void
  onScreenListChange?: (open: boolean) => void
  pinned?: boolean
  onTogglePin?: () => void
}

export function SpecDrawer({
  pageId, storage, currentAuthor, onClose, onDeleteElement, onSoftDeleteElement, onRestoreElement, onScreenSpecSaved, onElementSaved, refreshKey,
  pins = [], labels = [],
  selectedPinId = null, hoveredPinId = null,
  showResolved = false, resolvedCount = 0,
  onSelectPin, onHoverPin, onToggleShowResolved,
  defaultTab = 'screenSpec',
  sessions, currentSessionId, sessionProgress,
  onSelectSession, onCreateSession, onDeleteSession, onSetSessionStatus, onUpdateSession,
  onHoverElement, allAnnotations, onNavigate, onScreenListChange,
  pinned = false, onTogglePin,
}: Props) {
  const [tab, setTab] = useState<DrawerTab>(defaultTab)
  const [screens, setScreens] = useState<ScreenSpec[]>([])
  const [screensLoaded, setScreensLoaded] = useState(false)
  const [activePageId, setActivePageId] = useState(pageId)
  const [showScreenList, setShowScreenList] = useState(() => {
    try {
      const saved = localStorage.getItem('sb_screen_list_open')
      return saved === null ? true : saved === '1'
    } catch { return true }
  })

  const setShowScreenListPersisted = useCallback((v: boolean) => {
    setShowScreenList(v)
    try { localStorage.setItem('sb_screen_list_open', v ? '1' : '0') } catch {}
    onScreenListChange?.(v)
  }, [onScreenListChange])

  // 마운트 시 초기 상태 알림 — showScreenList 초기값과 동일한 로직 사용
  useEffect(() => {
    const saved = localStorage.getItem('sb_screen_list_open')
    onScreenListChange?.(saved === null ? true : saved === '1')
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // 화면 목록 활성 중 ESC → 전체 패널 닫기
  // 단, input/textarea에 포커스 중이면 무시 (수정 취소는 각 필드의 onKeyDown이 처리)
  useEffect(() => {
    if (!showScreenList) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== 'Escape') return
      const tag = (document.activeElement as HTMLElement)?.tagName
      if (tag === 'INPUT' || tag === 'TEXTAREA') return
      onClose()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [showScreenList, onClose])

  const handleSelectPage = (id: string) => {
    setActivePageId(id)
    onNavigate?.(id)
  }

  useEffect(() => {
    if (!storage.loadScreenSpecs) { setScreensLoaded(true); return }
    storage.loadScreenSpecs()
      .then(data => { setScreens(data); setScreensLoaded(true) })
      .catch(() => { setScreensLoaded(true) })
  }, [storage])

  useEffect(() => { setActivePageId(pageId) }, [pageId])

  const allScreens: ScreenSpec[] = screens.some(s => s.pageId === activePageId)
    ? screens
    : [{ id: null, pageId: activePageId, title: activePageId, description: '', status: 'draft' as SpecStatus, createdAt: null, updatedAt: null }, ...screens]

  const activeScreenTitle = allScreens.find(s => s.pageId === activePageId)?.title ?? activePageId
  const drawerPins: Pin[] = allAnnotations?.[activePageId] ?? (activePageId === pageId ? pins : [])

  const handleScreenSpecSaved = (spec: ScreenSpec) => {
    setScreens(prev => {
      const exists = prev.some(s => s.pageId === spec.pageId)
      return exists ? prev.map(s => s.pageId === spec.pageId ? spec : s) : [...prev, spec]
    })
    onScreenSpecSaved?.(spec)
  }

  const handleScreenDeleted = (pageId: string) => {
    setScreens(prev => prev.filter(s => s.pageId !== pageId))
  }

  const handleRenameScreen = async () => {
    const current = allScreens.find(s => s.pageId === activePageId)
    const name = window.prompt('화면 이름', current?.title || activePageId)
    if (!name?.trim() || !storage.saveScreenSpec) return
    const saved = await storage.saveScreenSpec(activePageId, { title: name.trim(), updatedBy: currentAuthor || null })
    setScreens(prev => {
      const exists = prev.some(s => s.pageId === activePageId)
      return exists ? prev.map(s => s.pageId === activePageId ? saved : s) : [...prev, saved]
    })
  }

  return (
    <div
      id="sb-spec-drawer"
      data-sb-ui="true"
      style={{
        position: 'fixed', top: 0, right: 0, bottom: 45, width: DRAWER_W,
        background: DARK.bg,
        borderLeft: `1px solid ${DARK.brd}`,
        boxShadow: '-4px 0 24px rgba(0,0,0,.3)',
        display: 'flex', flexDirection: 'column',
        zIndex: 9995, fontFamily: FONT_FAMILY,
      }}
    >
      {/* AnnotList 동일한 scrollbar 스타일 */}
      <style>{`
        .sb-scroll::-webkit-scrollbar{width:4px}
        .sb-scroll::-webkit-scrollbar-track{background:transparent}
        .sb-scroll::-webkit-scrollbar-thumb{background:rgba(255,255,255,.14);border-radius:10px}
        .sb-scroll::-webkit-scrollbar-thumb:hover{background:rgba(255,255,255,.26)}
        .sb-scroll{scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.14) transparent}
      `}</style>

      {/* 화면 목록 패널 */}
      {showScreenList && (
        <ScreenListPanel
          screens={allScreens}
          currentPageId={activePageId}
          onSelect={handleSelectPage}
          allAnnotations={allAnnotations}
          storage={storage}
          currentAuthor={currentAuthor}
          onScreenAdded={handleScreenSpecSaved}
          onScreenDeleted={handleScreenDeleted}
          screensLoaded={screensLoaded}
        />
      )}

      {/* 헤더 — AnnotList 동일 패턴 */}
      <div style={{ padding: '14px 10px 0px', background: DARK.bg2, flexShrink: 0, borderBottom: `1px solid ${DARK.brd}` }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 7, minWidth: 0 }}>
            <button
              onClick={() => setShowScreenListPersisted(!showScreenList)}
              title="화면 목록"
              style={{
                background: showScreenList ? `${SPEC_COLOR}22` : 'transparent',
                border: `1px solid ${showScreenList ? SPEC_COLOR : DARK.brd}`,
                borderRadius: 2, color: showScreenList ? SPEC_COLOR : DARK.txL,
                fontSize: 10, padding: '2px 6px', cursor: 'pointer',
                fontFamily: FONT_FAMILY, flexShrink: 0, transition: 'all .15s',
              }}
              onMouseEnter={e => { if (!showScreenList) { e.currentTarget.style.borderColor = SPEC_COLOR; e.currentTarget.style.color = SPEC_COLOR } }}
              onMouseLeave={e => { if (!showScreenList) { e.currentTarget.style.borderColor = DARK.brd; e.currentTarget.style.color = DARK.txL } }}
            >≡</button>
            <ScreenSelector
              screens={allScreens}
              currentPageId={activePageId}
              onSelect={handleSelectPage}
            />
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 4, flexShrink: 0 }}>
            {onTogglePin && (
              <button
                onClick={onTogglePin}
                title={pinned ? '고정 해제 — 페이지 이동 시 패널이 닫힙니다' : '패널 고정 — 페이지 이동 시 패널이 유지됩니다'}
                style={{
                  width: 26, height: 26, borderRadius: 5, cursor: 'pointer', flexShrink: 0,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  background: pinned ? `${SPEC_COLOR}22` : 'rgba(255,255,255,.08)',
                  border: `1px solid ${pinned ? SPEC_COLOR + '88' : 'transparent'}`,
                  color: pinned ? SPEC_COLOR : DARK.txS,
                  transition: 'all .15s',
                }}
                onMouseEnter={e => { if (!pinned) { e.currentTarget.style.background = 'rgba(255,255,255,.14)'; e.currentTarget.style.color = DARK.txt } }}
                onMouseLeave={e => { if (!pinned) { e.currentTarget.style.background = 'rgba(255,255,255,.08)'; e.currentTarget.style.color = DARK.txS } }}
              >
                <svg width="12" height="12" viewBox="0 0 16 16" fill="currentColor" xmlns="http://www.w3.org/2000/svg">
                  <path d="M4.146.146A.5.5 0 0 1 4.5 0h7a.5.5 0 0 1 .5.5c0 .68-.342 1.174-.646 1.479-.126.125-.25.224-.354.298v4.431l.078.048c.203.127.476.314.751.555C12.36 7.775 13 8.527 13 9.5a.5.5 0 0 1-.5.5h-4v4.5c0 .276-.224 1.5-.5 1.5s-.5-1.224-.5-1.5V10h-4a.5.5 0 0 1-.5-.5c0-.973.64-1.725 1.17-2.189A5.921 5.921 0 0 1 5 6.708V2.277a2.77 2.77 0 0 1-.354-.298C4.342 1.674 4 1.179 4 .5a.5.5 0 0 1 .146-.354z"/>
                </svg>
              </button>
            )}
            <button
              onClick={onClose}
              style={{
                background: 'rgba(255,255,255,.08)', border: 'none',
                color: DARK.txS, width: 26, height: 26,
                borderRadius: 5, cursor: 'pointer', fontSize: 14, flexShrink: 0,
              }}
              onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,.14)' }}
              onMouseLeave={e => { e.currentTarget.style.background = 'rgba(255,255,255,.08)' }}
            >×</button>
          </div>
        </div>

        {/* 탭 */}
        <div style={{ display: 'flex', gap: 0, marginTop: 10 }}>
          {TABS.map(({ key, label }) => (
            <button key={key} onClick={() => setTab(key)} style={{
              padding: '4px 10px', background: 'transparent', border: 'none',
              borderBottom: `2px solid ${tab === key ? '#3b82f6' : 'transparent'}`,
              color: tab === key ? '#3b82f6' : DARK.txL,
              fontSize: 11, fontWeight: tab === key ? 700 : 400,
              cursor: 'pointer', fontFamily: FONT_FAMILY, transition: 'all .12s',
              display: 'flex', alignItems: 'center', gap: 4,
            }}>
              {label}
              {key === 'comment' && drawerPins.filter(p => p.status !== 'resolved').length > 0 && (
                <span style={{
                  fontSize: 9, fontWeight: 700, minWidth: 14, height: 14,
                  background: tab === 'comment' ? '#3b82f6' : 'rgba(255,255,255,.18)',
                  color: '#fff', borderRadius: 3, padding: '0 3px',
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                }}>{drawerPins.filter(p => p.status !== 'resolved').length}</span>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* 탭 콘텐츠 */}
      <div style={{ flex: 1, overflow: 'hidden' }}>
        {tab === 'screenSpec' && (
          <ScreenSpecTab
            key={activePageId}
            pageId={activePageId}
            storage={storage}
            currentAuthor={currentAuthor}
            onDeleteElement={onDeleteElement}
            onSoftDeleteElement={onSoftDeleteElement}
            onRestoreElement={onRestoreElement}
            onHoverElement={onHoverElement}
            onScreenSpecSaved={handleScreenSpecSaved}
            onElementSaved={onElementSaved}
            refreshKey={refreshKey}
            externalTitle={allScreens.find(s => s.pageId === activePageId)?.title}
          />
        )}
        {tab === 'comment' && (
          <CommentTab
            pins={drawerPins}
            labels={labels}
            screenTitle={activeScreenTitle}
            screenUpdatedAt={allScreens.find(s => s.pageId === activePageId)?.updatedAt ?? null}
            screenDescription={allScreens.find(s => s.pageId === activePageId)?.description ?? ''}
            selectedId={selectedPinId}
            hoveredId={hoveredPinId}
            showResolved={showResolved}
            resolvedCount={resolvedCount}
            onSelect={onSelectPin ?? (() => {})}
            onHover={onHoverPin}
            onToggleShowResolved={onToggleShowResolved ?? (() => {})}
            sessions={sessions}
            currentSessionId={currentSessionId}
            sessionProgress={sessionProgress}
            onSelectSession={onSelectSession}
            onCreateSession={onCreateSession}
            onDeleteSession={onDeleteSession}
            onSetSessionStatus={onSetSessionStatus}
            onUpdateSession={onUpdateSession}
          />
        )}
      </div>
    </div>
  )
}
